    c.save(); c.beginPath(); c.arc(5, 5, 4.95, 0, 7); c.clip();
    c.fillStyle = '#d4deea'; c.beginPath(); c.arc(5, 5, 5, 0, 7); c.arc(4.1, 4.1, 5, 0, 7); c.fill('evenodd');
    c.restore();
