        const w = f.cols * 2, h = f.rows * 2, px = 24 + ((62 - w) >> 1), py = y + ((46 - h) >> 1);
        ctx.fillStyle = INK; ctx.fillRect(px - 1, py - 1, w + 2, h + 2);
