      for (const rx of [4, 8]) { c.beginPath(); c.ellipse(13, 13, rx, 11, 0, 0, 7); c.stroke(); }
      c.lineWidth = 1.2; c.beginPath(); c.arc(13, 13, 11, 0, 7); c.stroke();
