    const sparks = Array.from({ length: 7 }, (_, i) => ({ x: 10 + Math.random() * 300, y: 20 + Math.random() * 150, c: GG_STARS[(i + 1) % GG_STARS.length], p: rnd(64) }));
    const planets = [['globe', 34, 66], ['small', 64, 148], ['moon', 286, 150], ['swirl', 232, 104], ['ringed', 276, 38]]
