      if (on) { fine(x + 3, 202, w - 6, 0.5, '#f8e8a8'); fine(x + 3, 217.5, w - 6, 0.5, '#a88030'); }
      text(label, x + (w >> 1) - label.length * 3, 206, 1, ok ? CREAM : '#b07868');
