  function drawPokerIcon(x, y) {
    drawCard({ r: 14, s: 1 }, x + 10, y + 4);
    drawCard({ r: 13, s: 0 }, x + 28, y + 10);
    for (let i = 0; i < 3; i++) drawRoll(x + 12 + i * 13, y + 50);
  }

  // pc: the ComputerScreen it runs on, which shuts down when the game is over.
  // table: played at the poker table in Cody's casino instead.
  function PokerApp(pc, table) {
    const START = 200, BLIND_EVERY = 4, SMALL_BLINDS = [2, 3, 5, 8, 12, 20, 30, 50, 80];
    // how the bots play: loose calls more, aggr raises more, bluff bets with nothing
    const BOTS = {
      Cody: { loose: 0.5, aggr: 0.6, bluff: 0.14, bg: '#3868c8', bust: "I guess I just won't eat this weekend :(" },
      Dmitriy: { loose: 0.1, aggr: 0.4, bluff: 0.05, bg: '#9868c8', bust: 'Spring rolls are overrated anyway...' },
    };
    // seats go round the table clockwise: you at the bottom, Cody left, Dmitriy right
    const seats = [
      { name: 'You', you: true, stack: START, cardX: 134, cardY: 122, chip: [120, 132] },
      { name: 'Cody', stack: START, px: 12, cardX: 12, cardY: 56, chip: [66, 64] },
      { name: 'Dmitriy', stack: START, px: 230, cardX: 258, cardY: 56, chip: [244, 64], right: true },
    ];
    for (const p of seats) Object.assign(p, { out: false, hand: [], folded: false, allIn: false, bet: 0, total: 0, acted: false, show: false, value: 0 });
    let button = Math.floor(Math.random() * 3), handNo = 0, deck = [], board = [], street = 0;
    let toAct = -1, curBet = 0, minRaise = 0, lines = [], state = 'play', timer = 0, next = null, think = 0;
    let btn = 1, raising = false, raiseTo = 0, t = 0, record = false;
    const after = (frames, fn) => { timer = frames; next = fn; };
    const sb = () => SMALL_BLINDS[Math.min(SMALL_BLINDS.length - 1, Math.floor(handNo / BLIND_EVERY))];
    const bb = () => sb() * 2;
    const live = () => seats.filter((p) => !p.out);
    const inHand = () => seats.filter((p) => !p.out && !p.folded);
    const canAct = () => inHand().filter((p) => !p.allIn);
    const nextSeat = (i, ok) => { for (let k = 1; k <= 3; k++) if (ok(seats[(i + k) % 3])) return (i + k) % 3; return -1; };
    const pot = () => seats.reduce((n, p) => n + p.total, 0);
    // "You raise" / "Cody raises"
    const does = (p, verb) => (p.you ? 'You ' + verb : p.name + ' ' + verb + 's');
    function put(p, amt) {
      amt = Math.min(amt, p.stack);
      p.stack -= amt; p.bet += amt; p.total += amt;
      if (!p.stack) p.allIn = true;
      if (amt > 0) flyRolls(p, amt);
    }
    // spring rolls fly from someone's stack into the pot: more for bigger amounts, up to 6
    const rolls = RollFlyer();
    function flyRolls(p, amt) {
      const [x0, y0] = p.you ? [40, 138] : [p.px + 28, 39];
      rolls.send(x0, y0, 134, 40, Math.min(6, 1 + Math.floor(amt / (bb() * 2))));
    }

    function startHand() {
      for (const p of seats) Object.assign(p, { hand: [], folded: p.out, allIn: false, bet: 0, total: 0, acted: false, show: false, value: 0 });
      deck = newDeck(); board = []; street = 0; state = 'play'; raising = false;
      button = nextSeat(button, (p) => !p.out);
      // heads-up, the button posts the small blind
      const sbSeat = live().length === 2 ? button : nextSeat(button, (p) => !p.out);
      const bbSeat = nextSeat(sbSeat, (p) => !p.out);
      put(seats[sbSeat], sb()); put(seats[bbSeat], bb());
      curBet = bb(); minRaise = bb();
      for (let k = 0; k < 2; k++) for (const p of live()) p.hand.push(deck.pop());
      lines = ['Hand ' + (handNo + 1) + '. Blinds ' + sb() + '/' + bb() + '.'];
      sfx('select');
      advance(bbSeat);
    }
    // After someone acts: pass the action on, or close the betting round.
    function advance(from) {
      toAct = -1;
      if (inHand().length === 1) { winUncontested(); return; }
      const needs = (p) => !p.out && !p.folded && !p.allIn && (!p.acted || p.bet < curBet);
      // a lone player who can still bet only has to act if they're behind
      const alone = canAct().length === 1 && canAct()[0].bet >= curBet;
      if (alone || !seats.some(needs)) { endStreet(); return; }
      toAct = nextSeat(from, needs); think = 0;
      if (seats[toAct].you) { btn = 1; raising = false; }
    }
    function endStreet() {
      for (const p of seats) { p.bet = 0; p.acted = false; }
      curBet = 0; minRaise = bb();
      if (street === 3) { after(30, showdown); return; }
      // nobody left to bet against: turn the hands over and run the board out
      const runOut = canAct().length <= 1;
      if (runOut) for (const p of inHand()) p.show = true;
      after(runOut ? 50 : 24, () => {
        street++;
        deck.pop(); // burn
        for (let i = street === 1 ? 3 : 1; i > 0; i--) board.push(deck.pop());
        sfx('putt');
        lines = [['', 'The flop.', 'The turn.', 'The river.'][street]];
        if (runOut) { endStreet(); return; }
        advance(button); // first to act after the flop: the next player after the button
      });
    }
    function act(i, kind, to) {
      const p = seats[i], call = curBet - p.bet;
      p.acted = true;
      if (kind === 'fold') { p.folded = true; lines = [does(p, 'fold') + '.']; sfx('select'); }
      else if (kind === 'call' || to <= curBet) {
        if (call <= 0) { lines = [does(p, 'check') + '.']; sfx('blip'); }
        else { put(p, call); lines = [does(p, 'call') + ' ' + p.bet + (p.allIn ? ', all in!' : '.')]; sfx('putt'); }
      } else {
        to = Math.min(to, p.bet + p.stack);
        const opened = curBet === 0;
        // a full raise sets the new minimum; either way everyone else has to answer it
        if (to - curBet >= minRaise) minRaise = to - curBet;
        put(p, to - p.bet); curBet = p.bet;
        for (const q of seats) if (q !== p) q.acted = false;
        lines = [does(p, opened ? 'bet' : 'raise') + (opened ? ' ' : ' to ') + p.bet + (p.allIn ? ', all in!' : '.')];
        sfx('menu');
      }
      toAct = -1;
      after(p.you ? 12 : 30, () => advance(i));
    }

    function winUncontested() {
      const w = inHand()[0], amt = pot();
      w.stack += amt;
      for (const p of seats) { p.total = 0; p.bet = 0; }
      lines = [does(w, 'take') + ' the pot of ' + amt + '.'];
      if (w.you) sfx('cup');
      state = 'result';
    }
    function showdown() {
      const contenders = inHand(), got = seats.map(() => 0);
      for (const p of contenders) { p.show = true; p.value = handValue(p.hand.concat(board)); }
      // Side pots: slice the contributions at each player's total, smallest first; each
      // slice goes to the best hand among those still in who paid into all of it.
      const levels = [...new Set(seats.map((p) => p.total).filter(Boolean))].sort((a, b) => a - b);
      let prev = 0;
      for (const lv of levels) {
        const chunk = seats.reduce((n, p) => n + Math.max(0, Math.min(p.total, lv) - prev), 0);
        let elig = contenders.filter((p) => p.total >= lv);
        if (!elig.length) elig = contenders.filter((p) => p.total === Math.max(...contenders.map((q) => q.total)));
        const best = Math.max(...elig.map((p) => p.value)), winners = elig.filter((p) => p.value === best);
        const share = Math.floor(chunk / winners.length);
        for (const w of winners) { w.stack += share; if (elig.length > 1) got[seats.indexOf(w)] += share; }
        // the odd roll of a split goes to the first winner after the button
        const odd = chunk - share * winners.length;
        if (odd) seats[nextSeat(button, (p) => winners.includes(p))].stack += odd;
        prev = lv;
      }
      for (const p of seats) { p.total = 0; p.bet = 0; }
      const winners = seats.filter((p, i) => got[i] > 0);
      lines = winners.slice(0, 2).map((p) => does(p, 'win') + ' ' + got[seats.indexOf(p)] + ' with ' + handName(p.value) + '.');
      if (winners.some((p) => p.you)) sfx('cup'); else sfx('bump');
      state = 'result';
    }
    function endHand() {
      handNo++;
      const busted = seats.filter((p) => !p.out && p.stack === 0);
      for (const p of busted) p.out = true;
      const bot = busted.find((p) => !p.you);
      if (seats[0].out) {
        // busted: you get kicked off the computer
        remove(self); if (pc) remove(pc);
        say("Go again. It's impossible to lose more than once while gambling.");
      } else if (live().length === 1) {
        lines = ['You won all ' + seats[0].stack + ' spring rolls!', bot ? bot.name + ': ' + BOTS[bot.name].bust : ''];
        finish();
      } else if (bot) {
        // let the loser have their say before the next hand
        lines = [bot.name + ' is out.', bot.name + ': ' + BOTS[bot.name].bust];
        state = 'busted';
      } else startHand();
    }
    function finish() { state = 'over'; t = 0; record = saveBest('poker', seats[0].stack); sfx('ding'); }
    function leave() {
      // walking away mid-hand forfeits what you've already put in
      if (state !== 'over') record = saveBest('poker', seats[0].stack);
      remove(self);
      if (state === 'over') { if (pc) remove(pc); say('This gambling thing is too easy. You should do it full time.'); return; }
      say((table ? 'You leave the table with ' : 'You log off with ') + seats[0].stack + ' spring rolls.' + (record ? ' A new record!' : ''));
    }

    // Cody and Dmitriy: estimate their chances against the hands still in, then weigh
    // that against the price of calling, each with their own habits.
    function botMove(i) {
      const p = seats[i], bot = BOTS[p.name], call = curBet - p.bet, potNow = pot();
      const opps = inHand().length - 1;
      const eq = pokerEquity(p.hand, board, opps, 250);
      const strength = eq * (opps + 1); // 1 = an average hand for this many players
      const odds = call / (potNow + call), r = Math.random();
      const canRaise = p.stack > call && canAct().some((q) => q !== p);
      const sized = (frac) => {
        const to = curBet + Math.max(minRaise, Math.round((potNow + call) * frac / sb()) * sb());
        return strength > 2.3 && r < 0.3 ? p.bet + p.stack : to;
      };
      if (canRaise && strength > 1.75 - bot.aggr * 0.5 && r < 0.35 + bot.aggr * 0.5) return ['raise', sized(0.5 + Math.random() * 0.6)];
      if (canRaise && call === 0 && r < bot.bluff) return ['raise', sized(0.6)];
      if (call === 0) return ['call'];
      if (eq + bot.loose * 0.12 >= odds) return ['call'];
      if (r < bot.bluff && call <= p.stack * 0.1) return ['call'];
      return ['fold'];
    }

    const askLeave = () => ask('Leave the table with ' + seats[0].stack + ' spring rolls?', ['LEAVE', 'KEEP PLAYING'], (i) => { if (i === 0) leave(); }, { taps: true });
    // what the mouse and taps can do right now (see pokerPick)
    function canDo() {
      const me = seats[0], turn = state === 'play' && !timer && toAct === 0;
      const maxTo = me.bet + me.stack, minTo = Math.min(maxTo, curBet + minRaise);
      return { turn, raising: turn && raising, btn, pick: (i) => { btn = i; }, bet: (x) => { raiseTo = betAt(x, minTo, maxTo, bb()); } };
    }

    startHand();
    const self = {
      music: 'poker', doing: 'poker',
      // The mouse and taps go by pokerPick. Between hands a click or a tap deals the next one, and once
      // it's over, carries on. The right button is B, and so is the window's x on Zin's computer.
      point(x, y, button) {
        if (button === 'b' || (!table && inBox(x, y, SW - 14, 1, 12, 12))) return 'b';
        if (state === 'over') return button;
        if (timer) return null;
        if (state !== 'play') return button && 'a';
        return pokerPick(canDo(), x, y, button, false);
      },
      tap(x, y) {
        if (state === 'over') return 'a';
        if (timer) return null;
        if (state !== 'play') return 'a';
        return pokerPick(canDo(), x, y, 'a', true);
      },
      update() {
        t++;
        rolls.update();
        if (timer > 0) {
          if (pressed.has('b')) askLeave();
          else if (--timer === 0 && next) { const f = next; next = null; f(); }
          return;
        }
        if (state === 'over') { if (t > 30 && (pressed.has('a') || pressed.has('b'))) leave(); return; }
        if (state === 'result' || state === 'busted') {
          if (pressed.has('a')) { sfx('select'); if (state === 'busted') startHand(); else endHand(); }
          else if (pressed.has('b')) askLeave();
          return;
        }
        if (toAct < 0) return;
        const p = seats[toAct];
        if (!p.you) {
          if (pressed.has('b')) { askLeave(); return; }
          if (++think < 40) return;
          const [kind, to] = botMove(toAct);
          act(toAct, kind, to);
          return;
        }
        const call = curBet - p.bet, maxTo = p.bet + p.stack;
        const canRaise = p.stack > call && canAct().some((q) => q !== p);
        if (raising) {
          const minTo = Math.min(maxTo, curBet + minRaise), step = bb();
          const nudge = (d) => { raiseTo = Math.max(minTo, Math.min(maxTo, raiseTo + d)); sfx('select'); };
          const rep = (k) => pressed.has(k) || (held[k] && t % 5 === 0);
          if (rep('right')) nudge(step);
          if (rep('left')) nudge(-step);
          if (rep('up')) nudge(step * 5);
          if (rep('down')) nudge(-step * 5);
          if (pressed.has('a')) { raising = false; act(0, 'raise', raiseTo); }
          else if (pressed.has('b')) { raising = false; sfx('select'); }
          return;
        }
        if (pressed.has('left')) { btn = (btn + 3) % 4; sfx('select'); }
        if (pressed.has('right')) { btn = (btn + 1) % 4; sfx('select'); }
        if (pressed.has('b')) { askLeave(); return; }
        if (pressed.has('a')) {
          if (btn === 0) act(0, 'fold');
          else if (btn === 1) act(0, 'call');
          else if (btn === 2) { if (canRaise) { raising = true; raiseTo = Math.min(maxTo, curBet + minRaise); sfx('select'); } else sfx('bump'); }
          else act(0, canRaise ? 'raise' : 'call', maxTo);
        }
      },
      draw() {
        drawCardTable("Spring Roll Hold'em", 'Blinds ' + sb() + '/' + bb(), table);
        const ink = table ? CREAM : INK, blink = (tick >> 4) & 1;
        // the pot and the board
        const ps = 'Pot ' + pot();
        drawRoll(160 - ps.length * 3 - 14, 41);
        text(ps, 160 - ps.length * 3, 41, 1, '#f8f8f8');
        for (let i = 0; i < 5; i++) {
          const x = 94 + i * 27, y = 54;
          if (board[i]) drawCard(board[i], x, y);
          else drawCardSpot(x, y, CARD_W, CARD_H);
        }
        // the players
        seats.forEach((p, i) => {
          const showFace = p.you || p.show;
          if (p.out) {
            if (!p.you) { drawAvatar(p.px, 26, '#686878'); text(p.name, p.px + 28, 28, 1, '#a8b0a8'); text('OUT', p.cardX + 14, 66, 1, '#a8b0a8'); }
            return;
          }
          if (!p.you) {
            drawAvatar(p.px, 26, BOTS[p.name].bg);
            if (toAct === i && blink) { ctx.fillStyle = '#f8e070'; ring(p.px - 2, 24, 28, 28); }
            text(p.name, p.px + 28, 28, 1, '#f8f8f8');
            drawRoll(p.px + 28, 39); text(String(p.stack), p.px + 42, 39, 1, '#f8f8f8');
          } else {
            text('You', 40, 126, 1, '#f8f8f8');
            drawRoll(40, 138); text(String(p.stack), 54, 138, 1, '#f8f8f8');
            if (toAct === i && blink) { ctx.fillStyle = '#f8e070'; ring(p.cardX - 2, p.cardY - 2, CARD_W * 2 + 6, CARD_H + 4); }
          }
          if (p.folded) {
            ctx.globalAlpha = 0.35;
            p.hand.forEach((c, k) => drawCard(c, p.cardX + k * 26, p.cardY, !showFace));
            ctx.globalAlpha = 1;
            text('FOLD', p.cardX + 13, p.cardY + 12, 1, '#f8f8f8');
          } else p.hand.forEach((c, k) => drawCard(c, p.cardX + k * 26, p.cardY, !showFace));
          // what they have in front of them this round, and their hand once it's shown
          const note = p.allIn ? 'All in' : p.bet ? 'Bet ' + p.bet : '';
          const ny = p.you ? p.cardY - 11 : p.cardY + CARD_H + 4;
          if (note) text(note, p.you ? 160 - note.length * 3 : p.right ? 308 - note.length * 6 : p.cardX, ny, 1, '#f8e070');
          if (showFace && !p.folded && board.length >= 3) {
            const hn = handName(handValue(p.hand.concat(board)));
            if (p.you) text(hn, 190, 138, 1, '#f8f8f8');
            else text(hn, p.right ? 308 - hn.length * 6 : p.cardX, ny + 11, 1, '#f8f8f8');
          }
          if (i === button) {
            const [cx, cy] = p.chip;
            fineDisc(cx + 5.5, cy + 5.5, 5.5, INK); fineDisc(cx + 5.5, cy + 5.5, 5, '#c8ccd8'); fineDisc(cx + 5, cy + 5, 4.5, '#f8f8f8');
            text('D', cx + 3, cy + 2, 1, INK);
          }
        });
        rolls.draw(); // spring rolls on their way into the pot
        drawCardLog(lines, table);
        // your controls
        const me = seats[0], myTurn = toAct === 0 && !timer && state === 'play';
        const call = Math.min(curBet - me.bet, me.stack);
        if (raising) {
          const minTo = Math.min(me.bet + me.stack, curBet + minRaise), maxTo = me.bet + me.stack;
          const lbl = (curBet ? 'Raise to ' : 'Bet ') + raiseTo + (raiseTo === maxTo ? ' (all in)' : '');
          drawCardButton(RAISE_BTN[0], RAISE_BTN[2], lbl, true, true, table); // (A bets it, and so does a click or a tap)
          drawBetBar(maxTo > minTo ? (raiseTo - minTo) / (maxTo - minTo) : 1);
          text('Arrows: amount  Space: OK  Esc: back', 10, 224, 1, ink);
        } else if (state === 'play') {
          const labels = ['Fold', call ? 'Call ' + call : 'Check', curBet ? 'Raise' : 'Bet', 'All in'];
          labels.forEach((l, i) => drawCardButton(6 + i * 78, 74, l, myTurn && i === btn, myTurn, table));
          text(myTurn ? 'Arrows: choose  Space: OK  Esc: leave' : 'Esc: leave the table', 10, 226, 1, ink);
        } else if (state !== 'over') text('Space: next hand   Esc: leave the table', 10, 214, 1, ink);
        if (state === 'over') doneBox(['You cleaned them out!',
          'Spring rolls: ' + seats[0].stack, record ? 'New record!' : 'Best ' + getBest('poker')], t);
      },
    };
    return self;
  }

  // ---------- the sign-up sheet: which live game to join, or start a new one ----------
  // At the booth by the rink's gate (g: 'hockey'), the casino's poker table ('poker') or the
  // lunch room's racing cabinet ('race'). The game server has as many games going at once as
  // people start (see server/tables.js), so this asks it what's on, every second while it's up,
  // and lists the ones with room: a lobby still filling up, a game on with a skater the
  // computer's playing (see sit in server/tables/hockey.js), or a table with a seat free, each
  // with who's there. Or you start a new one, which comes straight up if there's nothing to join:
  // for hockey it asks what size of game first, and for a race which track, and then you're in
  // its lobby.
  const newTable = (kind) => kind + ':' + Math.random().toString(36).slice(2, 10);
  function SignUp(g) {
    const hk = g === 'hockey', rc = g === 'race', sheet = mp.sheet = { g, list: null }, SHOWN = 5;
    const SIZES = rc ? RACE.TRACKS.map((tr) => [tr.name, tr.about])
      : [['1 ON 1', 'You and one other player'], ['2 ON 2', '2 to 4 players, and the computer fills in'], ['3 ON 3', '2 to 6 players, and the computer fills in']];
    // t: ticks it's been up; pick: the game picked (null for starting a new one); at: where that
    // is in the list, for when it's gone; first: the top game showing; sizes: asking what size
    // of game (size: the one picked)
    let t = 0, begun = false, pick = null, at = 0, first = 0, sizes = false, size = 0;
    const open = () => sheet.list.filter((x) => x.open > 0);
    const close = () => { remove(self); if (mp.sheet === sheet) mp.sheet = null; };
    const go = (Game) => { close(); sfx('menu'); if (hk) startFade(() => ui.push(Game()), '#f8f8f8'); else ui.push(Game()); };
    const startNew = () => {
      if (hk || rc) { sizes = true; sfx('select'); } else go(() => LivePoker(newTable('poker')));
    };
    const self = {
      update() {
        if (t++ % 60 === 0) wsSend({ k: 'ls', g });
        if (!sheet.list) {
          if (pressed.has('b') || t > 300) {
            close();
            if (t > 300) say('Nobody\'s answering about live games right now. Try again in a bit.');
            else sfx('select');
          }
          return;
        }
        const games = open();
        if (!begun) {
          begun = true;
          if (games.length) pick = games[0].t;
          else if (hk || rc) sizes = true;
          else { go(() => LivePoker(newTable('poker'))); return; }
        }
        if (sizes) {
          if (pressed.has('up')) { size = (size + SIZES.length - 1) % SIZES.length; sfx('select'); }
          if (pressed.has('down')) { size = (size + 1) % SIZES.length; sfx('select'); }
          if (pressed.has('a')) {
            const n = (size + 1) * 2, tr = size;
            go(rc ? () => LiveRace(newTable('race'), false, tr) : () => LiveHockey(n, newTable('hockey' + (size + 1))));
          } else if (pressed.has('b')) {
            sfx('select');
            if (games.length) sizes = false; else close();
          }
          return;
        }
        // (stay on the game you picked as the list changes, or if it's gone, where it was)
        let i = pick ? games.findIndex((x) => x.t === pick) : games.length;
        if (i < 0) i = Math.min(at, games.length);
        if (pressed.has('up')) { i = (i + games.length) % (games.length + 1); sfx('select'); }
        if (pressed.has('down')) { i = (i + 1) % (games.length + 1); sfx('select'); }
        at = i; pick = i < games.length ? games[i].t : null;
        first = Math.max(0, Math.min(first, games.length - SHOWN, i < games.length ? i : first));
        if (i < games.length && i >= first + SHOWN) first = i - SHOWN + 1;
        if (pressed.has('a')) {
          const x = games[i];
          if (!x) startNew();
          else go(() => (hk ? LiveHockey(x.size, x.t, true) : rc ? LiveRace(x.t, true) : LivePoker(x.t, true)));
        } else if (pressed.has('b')) { sfx('select'); close(); }
      },
      // the mouse: point at a size, a game or START A NEW one to pick it, and click to go
      point(x, y, button) {
        if (button === 'b') return 'b';
        if (!sheet.list || !begun || x < 12 || x >= SW - 12) return null;
        if (sizes) {
          const i = Math.floor((y - 53) / 32);
          if (i < 0 || i >= SIZES.length || y - 53 - i * 32 >= 25) return null;
          size = i;
          return 'a';
        }
        const games = open(), showing = Math.min(SHOWN, games.length - first), i = Math.floor((y - 41) / 28);
        let to;
        if (i >= 0 && i < showing && y - 41 - i * 28 < 25) to = games[first + i].t;
        else if (inBox(x, y, 12, 43 + Math.min(SHOWN, games.length) * 28, SW - 24, 14)) to = null;
        else return null;
        pick = to;
        return 'a';
      },
      wheel(d) { pressed.add(d > 0 ? 'down' : 'up'); },
      draw() {
        box(0, 0, SW, SH);
        const title = hk ? 'LIVE HOCKEY SIGN-UP' : rc ? 'LIVE RACE SIGN-UP' : 'LIVE HOLD\'EM TABLES';
        text(title, (SW - title.length * 6) >> 1, 10);
        if (!sheet.list || !begun) {
          ctext('Checking the sheet' + '.'.repeat(1 + ((tick >> 4) % 3)), 104);
          text('Esc: never mind', 10, SH - 18);
          return;
        }
        const games = open(), row = (y, on, a, b, w = SW - 24) => {
          if (on) {
            roundBox(12, y - 3, w, b ? 25 : 14, 2.5, 'rgba(120, 110, 90, 0.16)');
            text('>', 14, y);
          }
          text(a, 24, y);
          if (b) text(b, 24, y + 11, 1, col.mid);
        };
        if (sizes) {
          const what = rc ? 'Which track?' : 'What size of game?';
          ctext(sheet.list.length ? what : (rc ? 'Nobody\'s racing yet. ' : 'Nobody\'s playing yet. ') + what, 30);
          SIZES.forEach(([a, b], i) => row(56 + i * (SIZES.length > 4 ? 30 : 32), i === size, a, b));
          text('Arrows: choose  Space: OK  Esc: back', 10, SH - 18);
          return;
        }
        ctext(hk ? 'Join a game, or start a new one' : rc ? 'Join a race, or start a new one' : 'Pull up a chair, or start a new table', 26);
        // (with more than fit, the scroll bar goes down the right, beside them)
        const lots = games.length > SHOWN;
        games.slice(first, first + SHOWN).forEach((x, i) => row(44 + i * 28, x.t === pick, rc ? raceLine(x) : sheetLine(x, hk), sheetNames(x.who), SW - 24 - (lots ? 8 : 0)));
        scrollBar(SW - 13, 41, 44 + (SHOWN - 1) * 28 + 22, first, SHOWN, games.length);
        if (lots) {
          const more = first + 1 + '-' + (first + SHOWN) + ' of ' + games.length;
          text(more, SW - 12 - more.length * 6, 10, 1, col.mid);
        }
        const y = 44 + Math.min(SHOWN, games.length) * 28 + 2, full = sheet.list.length - games.length;
        row(y, !pick, hk ? 'START A NEW GAME' : rc ? 'START A NEW RACE' : 'START A NEW TABLE');
        if (!games.length) ctext('Nothing to join right now.', y + 20, col.mid);
        else if (full) ctext(full + ' more ' + (hk ? (full > 1 ? 'games are' : 'game is') : rc ? (full > 1 ? 'races are' : 'race is') : (full > 1 ? 'tables are' : 'table is')) + ' going, with no room.', y + 20, col.mid);
        text('Arrows: choose  Space: OK  Esc: back', 10, SH - 18);
      },
    };
    return self;
  }
  // a game's first line on the sign-up sheet: what it is and how much room it has
  function sheetLine(x, hk) {
    const left = x.open + (hk ? ' spot' : ' seat') + (x.open > 1 ? 's' : '') + ' open';
    if (!hk) return (x.ph === 'wait' ? 'Waiting for players' : 'Playing') + ': ' + left;
    const kind = x.size / 2 + ' ON ' + x.size / 2 + '  ';
    if (x.ph !== 'play' || !Array.isArray(x.sc)) return kind + 'In the lobby: ' + left;
    const when = x.ot ? 'overtime' : Math.floor(x.clk / 60) + ':' + String(x.clk % 60).padStart(2, '0') + ' left';
    return kind + 'Playing ' + x.sc[0] + '-' + x.sc[1] + ', ' + when + ': ' + left;
  }
  // ...or for a race: which track, and how many spots are left in its lobby
  function raceLine(x) {
    const tr = RACE.TRACKS[x.tr] || RACE.TRACKS[0];
    return tr.name + '  In the lobby: ' + x.open + ' spot' + (x.open > 1 ? 's' : '') + ' open';
  }
  // and its second: who's there, as many as fit
  function sheetNames(who) {
    let line = '';
    for (let i = 0; i < who.length; i++) {
      const next = (i ? line + ', ' : '') + who[i], rest = who.length - i - 1;
      if (next.length + (rest ? 8 : 0) > 46) return line + ' +' + (rest + 1) + ' more';
      line = next;
    }
    return line;
  }

  // ---------- Live Hold'em: a poker table in the casino, against other players ----------
  // Up to four people sit at a table at once. The game server deals and keeps the
  // rules (server/tables/poker.js); this shows what it says (mp.table.view, see view()
  // there) and sends what you do. You sit bottom left, and the others go round clockwise
  // from you. Sitting down mid-hand, you're dealt in from the next one. name is which table
  // (see server/tables.js), and join is for one picked off the sign-up sheet, which has to
  // still be there.
  const LIVE_SEAT_BG = ['#3868c8', '#9868c8', '#c86838', '#38a868'];
  const LIVE_BUY_IN = 200; // what everyone sits down with (BUY_IN in server/tables/poker.js)
  function LivePoker(name, join) {
    const tb = mp.table = { t: name || 'poker', j: !!join, view: null, out: null, asked: false };
    // where each seat goes, counting clockwise from yours: a for its face, c its cards,
    // d the dealer chip, and n its two lines of notes (its bet, then its hand or its
    // clock), which end at nx on a seat down the right
    const SPOTS = [
      { ax: 12, ay: 136, cx: 12, cy: 100, dx: 66, dy: 122, nx: 66, ny: 102 },
      { ax: 12, ay: 14, cx: 12, cy: 42, dx: 66, dy: 46, nx: 12, ny: 78 },
      { ax: 284, ay: 14, cx: 258, cy: 42, dx: 243, dy: 46, nx: 308, ny: 78, right: true },
      { ax: 284, ay: 136, cx: 258, cy: 100, dx: 243, dy: 122, nx: 254, ny: 102, right: true },
    ];
    const spot = (v, i) => SPOTS[(i - Math.max(0, v.me) + 4) % 4];
    // where a seat's little spring roll goes, with its stack written after it
    const stackAt = (sp, n) => (sp.right ? [sp.ax - 18 - String(n).length * 6, sp.ay + 13] : [sp.ax + 28, sp.ay + 13]);
    const rolls = RollFlyer();
    let btn = 1, raising = false, raiseTo = 0, t = 0, ev = -1, prev = null, acted = '';
    // a line to say to everyone else at the table (see GameChat)
    const others = () => { const v = tb.view; return v && !tb.out ? v.seats.filter((q, i) => q && i !== v.me).map((q) => q.id) : []; };
    const chat = GameChat(others, 'Say to the table:');
    // what the mouse and taps can do right now (see pokerPick)
    function canDo() {
      const v = tb.view, p = v.seats[v.me];
      const turn = !!p && v.ph === 'play' && v.act === v.me && acted !== v.hn + '/' + v.ev;
      const maxTo = p ? p.b + p.st : 0, minTo = Math.min(maxTo, v.bet + v.min);
      return { turn, raising: turn && raising, btn, pick: (i) => { btn = i; }, bet: (x) => { raiseTo = betAt(x, minTo, maxTo, v.bb); } };
    }

    // a new view from the server: play its sound, and send spring rolls flying into the
    // pot for a bet and out of it to whoever won
    function hear(v, old) {
      if (v.ev !== ev && ev >= 0) {
        if (v.snd.startsWith('win:')) sfx(v.snd.slice(4).split(',').map(Number).includes(v.me) ? 'cup' : 'bump');
        else sfx({ deal: 'select', card: 'putt', fold: 'select', check: 'blip', call: 'putt', raise: 'menu' }[v.snd] || 'select');
      }
      ev = v.ev;
      if (old) v.seats.forEach((q, i) => {
        const o = old.seats[i];
        if (!q || !o || o.id !== q.id) return;
        const [x, y] = stackAt(spot(v, i), q.st), fly = (n) => Math.min(6, 1 + Math.floor(n / (v.bb * 2)));
        const was = old.hn === v.hn ? o.b : 0;
        if (q.b > was) rolls.send(x, y, 134, 40, fly(q.b - was));
        else if (old.hn === v.hn && q.st > o.st) rolls.send(134, 40, x, y, fly(q.st - o.st));
      });
      if (v.ph === 'play' && v.act === v.me && (!old || old.act !== v.me)) { sfx('ding'); btn = 1; }
    }
    // What each hand comes to, for the board (netNote): your stack once it's over against
    // your stack once the last one was (or the buy-in). Getting up partway through a hand
    // leaves what you'd put in in the pot. A hand whose end goes by unseen (the tab was
    // hidden, say) is counted in with the next one.
    let base = -1, lastSt = 0, doneHn = -1, played = false;
    const settle = (st) => { if (base >= 0) netNote('pokerlive', st - base); base = st; };
    function tally(v) {
      const p = v.seats[v.me];
      if (!p) return;
      if (base < 0) base = LIVE_BUY_IN; // you're sitting down
      if (p.d) played = true;
      lastSt = p.st;
      if (v.ph === 'result' && v.hn !== doneHn) { doneHn = v.hn; settle(p.st); }
    }
    // Up from the table: the board goes up once you've played a hand. The latest view
    // first, since the table may have played on while you weren't looking (asked whether
    // to leave, say, or in another tab).
    const gone = () => {
      remove(self); if (mp.table === tb) mp.table = null;
      chat.close();
      if (tb.view && tb.view !== prev) tally(tb.view);
      settle(lastSt);
      if (played && (BOARD_URL || boardDemo)) pendingBoard = { key: 'pokerlive', score: 0, owner: self };
    };
    const myStack = () => { const v = tb.view, p = v && v.seats[v.me]; return p ? p.st : 0; };
    function leave() {
      wsSend({ k: 'stand', t: tb.t });
      gone();
      say('You leave the table with ' + myStack() + ' spring rolls.');
    }
    const askLeave = () => ask('Leave the table with ' + myStack() + ' spring rolls?', ['LEAVE', 'KEEP PLAYING'], (i) => { if (i === 0) leave(); }, { taps: true });

    const self = {
      music: 'poker', chat,
      // the mouse and taps (see pokerPick), and the right button is B
      point(x, y, button) {
        if (chat.typing) return chat.point(x, y, button);
        if (button === 'b') return 'b';
        return tb.view ? pokerPick(canDo(), x, y, button, false) : null;
      },
      tap(x, y) { return chat.typing || !tb.view ? null : pokerPick(canDo(), x, y, 'a', true); },
      // over your head for everyone else: waiting for someone to play with, or how many are playing
      get doing() { return tb.view && tb.view.ph !== 'wait' ? 'pokerlive' : 'pokerwait'; },
      get seated() { return tb.view ? tb.view.seats.filter(Boolean).length : 0; },
      update() {
        t++;
        rolls.update();
        if (tb.out) {
          gone();
          say({
            full: 'All four seats at that table are taken. Try another, or play solo.',
            ended: 'That table has packed up. Try another, or play solo.',
            many: 'Zin has too many tables going right now. Try again in a bit, or play solo.',
            bust: 'You\'re out of spring rolls! Sit back down any time for another 200.',
            idle: 'You took too long, so Zin gave your seat to someone else.',
          }[tb.out] || 'You lost your seat at the table. The connection to the game server dropped.');
          return;
        }
        const v = tb.view;
        if (!v) {
          // sit down once the server's there and knows who you are
          if (!tb.asked && ws.sock && ws.sock.readyState === 1 && mp.sentKey) { tb.asked = true; wsSend({ k: 'sit', t: tb.t, j: tb.j }); }
          if (pressed.has('b') || t > 600) {
            if (tb.asked) wsSend({ k: 'stand', t: tb.t });
            gone();
            if (t > 600) say('The live table isn\'t answering right now. Try again in a bit, or play solo.');
            else sfx('select');
          }
          return;
        }
        if (v !== prev) { hear(v, prev); tally(v); prev = v; }
        // (while the bar to say something in is up, the buttons are its)
        if (chat.update()) return;
        // your turn, unless you've already said what you're doing and the server's yet to hear
        const p = v.seats[v.me], key = v.hn + '/' + v.ev;
        const myTurn = !!p && v.ph === 'play' && v.act === v.me && acted !== key;
        const send = (a, to) => { acted = key; raising = false; wsSend({ k: 'tin', t: tb.t, d: { a, to } }); };
        if (raising && myTurn) {
          const maxTo = p.b + p.st, minTo = Math.min(maxTo, v.bet + v.min), step = v.bb;
          const nudge = (d) => { raiseTo = Math.max(minTo, Math.min(maxTo, raiseTo + d)); sfx('select'); };
          const rep = (k) => pressed.has(k) || (held[k] && t % 5 === 0);
          if (rep('right')) nudge(step);
          if (rep('left')) nudge(-step);
          if (rep('up')) nudge(step * 5);
          if (rep('down')) nudge(-step * 5);
          if (pressed.has('a')) send('raise', raiseTo);
          else if (pressed.has('b')) { raising = false; sfx('select'); }
          return;
        }
        raising = false;
        if (pressed.has('b')) { askLeave(); return; }
        if (!myTurn) return;
        const call = v.bet - p.b, maxTo = p.b + p.st;
        const canRaise = p.st > call && v.seats.some((q, i) => q && i !== v.me && q.d && !q.f && !q.ai);
        if (pressed.has('left')) { btn = (btn + 3) % 4; sfx('select'); }
        if (pressed.has('right')) { btn = (btn + 1) % 4; sfx('select'); }
        if (pressed.has('a')) {
          if (btn === 0) send('fold');
          else if (btn === 1) send('call');
          else if (btn === 2) { if (canRaise) { raising = true; raiseTo = Math.min(maxTo, v.bet + v.min); sfx('select'); } else sfx('bump'); }
          else send(canRaise ? 'raise' : 'call', maxTo);
        }
      },
      draw() {
        const v = tb.view, blink = (tick >> 4) & 1, dots = '.'.repeat(1 + ((tick >> 4) % 3));
        // (short, so the names on the seats either side of it fit)
        drawCardTable("Live Hold'em", v ? 'Blinds ' + v.sb + '/' + v.bb : '', true);
        if (!v) {
          ctext('Finding you a seat' + dots, 80, CREAM);
          drawCardLog([], true);
          text('Esc: never mind', 10, 214, 1, CREAM);
          return;
        }
        // the pot and the board
        const ps = 'Pot ' + v.pot;
        drawRoll(160 - ps.length * 3 - 14, 41);
        text(ps, 160 - ps.length * 3, 41, 1, '#f8f8f8');
        for (let i = 0; i < 5; i++) {
          const x = 94 + i * 27, y = 54;
          if (v.board[i]) drawCard(v.board[i], x, y);
          else drawCardSpot(x, y, CARD_W, CARD_H);
        }
        v.seats.forEach((q, i) => drawSeat(v, q, i, blink));
        const p = v.seats[v.me];
        if (v.ph === 'wait') ctext('Waiting for another player' + dots, 136, CREAM);
        else if (p && !p.d) ctext('You\'re in from the next hand.', 136, CREAM);
        rolls.draw();
        // what anyone's just said, beside their picture (over their name)
        v.seats.forEach((q, i) => {
          const said = q && chat.line(i === v.me ? '' : q.id);
          if (!said) return;
          const sp = spot(v, i), b = chatBox(said, 18);
          chatBubble(b, sp.right ? sp.ax - 4 - b.w : sp.ax + 28, sp.ay - 1, sp.right ? 'right' : 'left', sp.ay + 12);
        });
        drawCardLog(v.log, true);
        // your controls
        const myTurn = !!p && v.ph === 'play' && v.act === v.me && acted !== v.hn + '/' + v.ev;
        const chatHint = others().length ? '   Enter: chat' : ''; // (not on your go: there isn't room)
        if (raising && myTurn) {
          const maxTo = p.b + p.st, minTo = Math.min(maxTo, v.bet + v.min);
          const lbl = (v.bet ? 'Raise to ' : 'Bet ') + raiseTo + (raiseTo === maxTo ? ' (all in)' : '');
          drawCardButton(RAISE_BTN[0], RAISE_BTN[2], lbl, true, true, true); // (A bets it, and so does a click or a tap)
          drawBetBar(maxTo > minTo ? (raiseTo - minTo) / (maxTo - minTo) : 1);
          text('Arrows: amount  Space: OK  Esc: back', 10, 224, 1, CREAM);
        } else if (p && p.d && v.ph === 'play') {
          const call = Math.min(v.bet - p.b, p.st);
          const labels = ['Fold', call ? 'Call ' + call : 'Check', v.bet ? 'Raise' : 'Bet', 'All in'];
          labels.forEach((l, i) => drawCardButton(6 + i * 78, 74, l, myTurn && i === btn, myTurn, true));
          text(myTurn ? 'Arrows: choose  Space: OK  Esc: leave' : 'Esc: leave the table' + chatHint, 10, 226, 1, CREAM);
        } else text('Esc: leave the table' + chatHint, 10, 214, 1, CREAM);
        if (myTurn) text(v.clk + 's', 310 - String(v.clk).length * 6 - 6, raising ? 224 : 226, 1, v.clk <= 10 && blink ? '#f87050' : CREAM);
        chat.draw(top() === self);
      },
    };

    function drawSeat(v, q, i, blink) {
      const sp = spot(v, i), mine = i === v.me;
      // text that lines up to the left of x on a seat down the right
      const write = (str, x, y, c) => text(str, sp.right ? x - str.length * 6 : x, y, 1, c);
      const nameX = sp.right ? sp.ax - 4 : sp.ax + 28;
      if (!q) {
        drawCardSpot(sp.ax, sp.ay, 24, 24);
        write('Empty seat', nameX, sp.ay + 2, '#88c898');
        return;
      }
      // their face: the character they're playing as
      const o = mp.others[q.id], sheet = mine ? sprites : o ? mpSprites(o) : null;
      drawAvatar(sp.ax, sp.ay, LIVE_SEAT_BG[i]);
      if (sheet) {
        ctx.fillStyle = LIVE_SEAT_BG[i]; ctx.fillRect(sp.ax + 1, sp.ay + 1, 22, 22);
        ctx.drawImage(sheet.down[0], sp.ax + 4, sp.ay + 5);
      }
      const turn = v.ph === 'play' && v.act === i;
      if (turn && blink) { ctx.fillStyle = '#f8e070'; ring(sp.ax - 2, sp.ay - 2, 28, 28); ring(sp.cx - 2, sp.cy - 2, CARD_W * 2 + 6, CARD_H + 4); }
      write(mine ? 'You' : q.n, nameX, sp.ay + 2, '#f8f8f8');
      const [rx, ry] = stackAt(sp, q.st);
      drawRoll(rx, ry); text(String(q.st), rx + 14, ry, 1, '#f8f8f8');
      if (!q.d) { text('Waiting', sp.cx + 4, sp.cy + 12, 1, '#88c898'); return; }
      if (q.f) ctx.globalAlpha = 0.35;
      q.h.forEach((c, k) => drawCard(c || null, sp.cx + k * 26, sp.cy, !c));
      ctx.globalAlpha = 1;
      if (q.f) text('FOLD', sp.cx + 13, sp.cy + 12, 1, '#f8f8f8');
      // what they've put in this round, then their hand once you can see it (or how long
      // they've got left to act)
      const note = q.ai ? 'All in' : q.b ? 'Bet ' + q.b : '';
      if (note) write(note, sp.nx, sp.ny, '#f8e070');
      let hn = '';
      if (!q.f && q.h[0] && v.board.length >= 3) hn = handName(handValue(q.h.concat(v.board)));
      if (turn && !mine) hn = v.clk + 's';
      if (hn) write(hn, sp.nx, sp.ny + 11, '#f8f8f8');
      if (i === v.btn && v.ph !== 'wait') {
        const cx = sp.dx, cy = sp.dy;
        ctx.fillStyle = INK; ctx.fillRect(cx, cy + 1, 11, 9); ctx.fillRect(cx + 1, cy, 9, 11);
        ctx.fillStyle = '#f8f8f8'; ctx.fillRect(cx + 1, cy + 1, 9, 9);
        text('D', cx + 3, cy + 2, 1, INK);
      }
    }
    return self;
  }

  // ---------- Spring Roll Blackjack: on Cody's computer ----------
  // You against the house, played for the same spring rolls as Hold'em. You start
  // with START rolls; blackjack pays 3 to 2 and the dealer stands on all 17s.
  // Break the bank (GOAL rolls) to win, or lose them all and get kicked off.
  function drawBlackjackIcon(x, y) {
    drawCard({ r: 14, s: 0 }, x + 10, y + 4);
    drawCard({ r: 11, s: 1 }, x + 28, y + 10);
    for (let i = 0; i < 3; i++) drawRoll(x + 12 + i * 13, y + 50);
  }
  // a hand's best total, and whether an ace is still counting as 11
  function bjTotal(hand) {
    let n = 0, aces = 0;
    for (const c of hand) { n += c.r === 14 ? 11 : Math.min(10, c.r); if (c.r === 14) aces++; }
    while (n > 21 && aces) { n -= 10; aces--; }
    return { n, soft: aces > 0 };
  }
  const isBlackjack = (hand) => hand.length === 2 && bjTotal(hand).n === 21;

  // pc: the ComputerScreen it runs on, which shuts down when the game is over.
  // table: played at Cody's blackjack table in his casino instead.
  function BlackjackApp(pc, table) {
    const START = 200, GOAL = 1000, MIN_BET = 10, DECKS = 4;
    let stack = START, bet = MIN_BET, wager = 0, shoe = [], me = [], dealer = [], holeHidden = true;
    let state = 'bet', lines = [], btn = 0, timer = 0, next = null, t = 0, record = false;
    const after = (frames, fn) => { timer = frames; next = fn; };
    // spring rolls flying between your stack, the bet spot and the dealer
    const rolls = RollFlyer(), YOU = [20, 136], BET = [130, 146], DEALER = [42, 40];
    const count = (amt) => Math.min(6, 1 + Math.floor(amt / 20));
    const toBet = (amt) => rolls.send(YOU[0], YOU[1], BET[0], BET[1], count(amt));
    // run fns one after another, a beat apart, then done()
    const steps = (fns, done) => {
      if (!fns.length) { done(); return; }
      fns[0](); after(16, () => steps(fns.slice(1), done));
    };
    const draw1 = (hand) => () => { hand.push(shoe.pop()); sfx('putt'); };
    function shuffle() {
      shoe = [];
      for (let d = 0; d < DECKS; d++) shoe.push(...newDeck());
      for (let i = shoe.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [shoe[i], shoe[j]] = [shoe[j], shoe[i]]; }
    }
    shuffle();
    const fixBet = () => { bet = Math.max(Math.min(MIN_BET, stack), Math.min(stack, bet)); };
    lines = ['Welcome to Spring Roll Blackjack!', 'Blackjack pays 3 to 2. Place your bet.'];
    fixBet();

    function deal() {
      const reshuffled = shoe.length < 60;
      if (reshuffled) shuffle();
      wager = bet; stack -= wager; toBet(wager);
      me = []; dealer = []; holeHidden = true; state = 'deal'; btn = 0;
      lines = [(reshuffled ? 'Fresh shoe. ' : '') + 'You bet ' + wager + ' spring rolls.'];
      sfx('select');
      steps([draw1(me), draw1(dealer), draw1(me), draw1(dealer)], () => {
        const up = dealer[0].r;
        // the dealer peeks under an ace or a ten-card for blackjack
        if (isBlackjack(dealer) && (up === 14 || up >= 10)) { holeHidden = false; settle(); return; }
        if (isBlackjack(me)) { holeHidden = false; settle(); return; }
        state = 'play';
        lines = ['You have ' + totalText(me) + '. Dealer shows ' + RANK_TXT(up) + '.'];
      });
    }
    const totalText = (hand) => { const v = bjTotal(hand); return (v.soft && v.n < 21 ? 'soft ' : '') + v.n; };
    const canDouble = () => state === 'play' && me.length === 2 && stack >= wager;

    function hit() {
      sfx('putt'); me.push(shoe.pop());
      const v = bjTotal(me).n;
      if (v > 21) { state = 'wait'; lines = ['You bust with ' + v + '.']; after(30, () => { holeHidden = false; settle(); }); }
      else if (v === 21) { state = 'wait'; lines = ['21!']; after(24, dealerPlays); }
      else lines = ['You have ' + totalText(me) + '.'];
    }
    function double() {
      toBet(wager); stack -= wager; wager *= 2;
      sfx('menu'); me.push(shoe.pop());
      state = 'wait';
      const v = bjTotal(me).n;
      lines = ['You double down to ' + wager + ' and draw ' + v + '.'];
      after(30, () => { if (v > 21) { holeHidden = false; settle(); } else dealerPlays(); });
    }
    function dealerPlays() {
      state = 'wait'; holeHidden = false; sfx('blip');
      lines = ['Dealer turns over ' + totalText(dealer) + '.'];
      const go = () => {
        if (bjTotal(dealer).n < 17) {
          after(30, () => { draw1(dealer)(); lines = ['Dealer draws to ' + totalText(dealer) + '.']; go(); });
        } else after(30, settle);
      };
      go();
    }
    // pay out (or not) and show what happened
    function settle() {
      const mine = bjTotal(me).n, theirs = bjTotal(dealer).n;
      const myBJ = isBlackjack(me), theirBJ = isBlackjack(dealer);
      let won = 0, msg;
      if (myBJ && theirBJ) { won = wager; msg = 'Both blackjack. Push.'; }
      else if (myBJ) { won = wager + Math.floor(wager * 1.5); msg = 'Blackjack! You win ' + (won - wager) + '.'; }
      else if (theirBJ) msg = 'Dealer has blackjack. You lose ' + wager + '.';
      else if (mine > 21) msg = 'Bust. You lose ' + wager + '.';
      else if (theirs > 21) { won = wager * 2; msg = 'Dealer busts with ' + theirs + '! You win ' + wager + '.'; }
      else if (mine > theirs) { won = wager * 2; msg = mine + ' beats ' + theirs + '. You win ' + wager + '.'; }
      else if (mine === theirs) { won = wager; msg = 'Push at ' + mine + '. Bet back.'; }
      else msg = theirs + ' beats ' + mine + '. You lose ' + wager + '.';
      stack += won;
      // the bet goes to the dealer, or comes back to you with any winnings
      if (won === 0) rolls.send(BET[0], BET[1], DEALER[0], DEALER[1], count(wager));
      else {
        rolls.send(BET[0], BET[1], YOU[0], YOU[1], count(Math.min(won, wager)));
        if (won > wager) rolls.send(DEALER[0], DEALER[1], YOU[0], YOU[1], count(won - wager));
      }
      lines = [msg, 'You have ' + stack + ' spring rolls.'];
      if (won > wager) sfx('cup'); else if (won < wager) sfx('bump'); else sfx('blip');
      wager = 0; state = 'result';
    }
    function nextHand() {
      if (stack <= 0) {
        // busted: you get kicked off the computer
        remove(self); if (pc) remove(pc);
        say("Cody: Don't worry, the house always wins. That's how I lose mine too.");
        return;
      }
      if (stack >= GOAL) { state = 'over'; t = 0; record = saveBest('blackjack', stack); sfx('ding'); return; }
      fixBet(); me = []; dealer = []; state = 'bet';
      lines = ['Place your bet.'];
    }
    function leave() {
      // walking away mid-hand forfeits the bet on the table
      if (state !== 'over') record = saveBest('blackjack', stack);
      remove(self);
      if (state === 'over') { if (pc) remove(pc); say('You broke the bank ' + (table ? 'at Cody\'s table' : 'on Cody\'s computer') + '. He looks nervous.'); return; }
      say((table ? 'You leave the table with ' : 'You log off with ') + stack + ' spring rolls.' + (record ? ' A new record!' : ''));
    }
    const askLeave = () => ask('Leave the table with ' + stack + ' spring rolls?', ['LEAVE', 'KEEP PLAYING'], (i) => { if (i === 0) leave(); });

    const self = {
      music: 'poker', doing: 'blackjack',
      update() {
        t++;
        rolls.update();
        if (timer > 0) {
          if (pressed.has('b')) askLeave();
          else if (--timer === 0 && next) { const f = next; next = null; f(); }
          return;
        }
        if (state === 'over') { if (t > 30 && (pressed.has('a') || pressed.has('b'))) leave(); return; }
        if (pressed.has('b')) { askLeave(); return; }
        if (state === 'result') { if (pressed.has('a')) { sfx('select'); nextHand(); } return; }
        if (state === 'bet') {
          const nudge = (d) => {
            const b = Math.max(Math.min(MIN_BET, stack), Math.min(stack, bet + d));
            if (b !== bet) { bet = b; sfx('select'); }
          };
          const rep = (k) => pressed.has(k) || (held[k] && t % 5 === 0);
          if (rep('right')) nudge(MIN_BET);
          if (rep('left')) nudge(-MIN_BET);
          if (rep('up')) nudge(MIN_BET * 5);
          if (rep('down')) nudge(-MIN_BET * 5);
          if (pressed.has('a')) deal();
          return;
        }
        if (state !== 'play') return;
        if (pressed.has('left')) { btn = (btn + 2) % 3; sfx('select'); }
        if (pressed.has('right')) { btn = (btn + 1) % 3; sfx('select'); }
        if (pressed.has('a')) {
          if (btn === 0) hit();
          else if (btn === 1) { lines = ['You stand on ' + bjTotal(me).n + '.']; dealerPlays(); }
          else if (canDouble()) double();
          else sfx('bump');
        }
      },
      draw() {
        drawCardTable('Spring Roll Blackjack', 'Goal ' + GOAL, table);
        const felt = '#88c898', ink = table ? CREAM : INK;
        text('BLACKJACK PAYS 3 TO 2', 160 - 21 * 3, 80, 1, felt);
        text('Dealer stands on all 17s', 160 - 24 * 3, 91, 1, felt);
        // a hand of cards, centred, squeezed together when it gets long
        const row = (hand, y, hideSecond) => {
          if (!hand.length) { drawCardSpot(160 - CARD_W - 1, y, CARD_W, CARD_H); drawCardSpot(161, y, CARD_W, CARD_H); return; }
          const gap = hand.length > 6 ? 16 : 26, w = (hand.length - 1) * gap + CARD_W;
          hand.forEach((c, i) => drawCard(c, 160 - (w >> 1) + i * gap, y, hideSecond && i === 1));
        };
        // dealer
        drawAvatar(14, 28, '#3868c8');
        text('Dealer', 42, 30, 1, '#f8f8f8');
        row(dealer, 34, holeHidden);
        if (dealer.length) {
          const dt = holeHidden ? RANK_TXT(dealer[0].r) + ' + ?' : totalText(dealer);
          text(dt, 238, 46, 1, '#f8f8f8');
        }
        // you
        text('You', 20, 124, 1, '#f8f8f8');
        drawRoll(20, 136); text(String(stack), 34, 136, 1, '#f8f8f8');
        row(me, 104, false);
        if (me.length) text(totalText(me), 238, 116, 1, '#f8f8f8');
        const shown = state === 'bet' ? bet : wager;
        if (shown) {
          const bs = 'Bet ' + shown;
          drawRoll(160 - bs.length * 3 - 14, 146);
          text(bs, 160 - bs.length * 3, 146, 1, '#f8e070');
        }
        rolls.draw();
        drawCardLog(lines, table);
        // your controls
        if (state === 'bet') {
          text('Bet ' + bet + (bet === stack ? ' (all in)' : ''), 10, 204, 1, ink);
          drawBetBar(Math.min(1, bet / Math.max(1, stack)));
          text('Arrows: bet  Space: deal  Esc: leave', 10, 224, 1, ink);
        } else if (state === 'play' || state === 'deal' || state === 'wait') {
          const myTurn = state === 'play' && !timer;
          ['Hit', 'Stand', 'Double'].forEach((l, i) => drawCardButton(6 + i * 104, 100, l, myTurn && i === btn, myTurn && (i < 2 || canDouble()), table));
          text(myTurn ? 'Arrows: choose  Space: OK  Esc: leave' : 'Esc: leave the table', 10, 226, 1, ink);
        } else if (state === 'result') text('Space: next hand   Esc: leave the table', 10, 214, 1, ink);
        if (state === 'over') doneBox(['You broke the bank!',
          'Spring rolls: ' + stack, record ? 'New record!' : 'Best ' + getBest('blackjack')], t);
      },
    };
    return self;
  }

  // ---------- Spring Roll Slots: the slot machines in Cody's casino ----------
  // Three reels and one payline, played for the same spring rolls as the card games: you
  // start with START and clean out the machine at GOAL. Every reel has the same 20 stops
  // (SLOT_STRIP), so with SLOT_PAYS the machine pays back about 94% of what goes in.
  const SLOT_STRIP = ['7', 'lemon', 'cherry', 'roll', 'lemon', 'bell', 'cherry', 'lemon', 'bar', 'roll',
    'lemon', 'cherry', 'bell', 'roll', 'lemon', 'bar', 'cherry', 'roll', 'lemon', 'bell'];
  // three of a kind on the line pays this many times your bet; any two cherries pay 4
  // times, and a cherry on the left reel gives you your bet back
  const SLOT_PAYS = { 7: 100, bar: 40, bell: 20, roll: 12, cherry: 10, lemon: 5 };
  const SLOT_NAMES = { 7: 'sevens', bar: 'bars', bell: 'bells', roll: 'spring rolls', cherry: 'cherries', lemon: 'lemons' };
  const SLOT_PIX = {
    7: ['kkkkkkkkkkkk', 'kRRRRRRRRRRk', 'krrrrrrrrrrk', 'kkkkkkkkrrrk', '......krrrk.', '.....krrrk..',
      '....krrrk...', '....krrk....', '...krrrk....', '...krrk.....', '...krrk.....', '...kkkk.....'],
    bell: ['.....kk.....', '....kyok....', '...kyoook...', '...kyoook...', '..kyoooonk..', '..kyoooonk..',
      '.kyoooooonk.', 'kyooooooonnk', 'kkkkkkkkkkkk', '.knnnnnnnnk.', '..kkkkkkkk..', '.....kk.....'],
    cherry: ['........ggG.', '.......g.gGG', '......g..g..', '.....g...g..', '....g....g..', '...g.....g..',
      '.kkkk..kkkk.', 'kRrrrkkRrrrk', 'krrrrkkrrrrk', 'krrrrkkrrrrk', '.kkkk..kkkk.', '............'],
    lemon: ['............', '....kkkk....', '..kkllllkk..', '.kllwwlllLk.', 'kllwlllllLLk', 'klllllllllLk',
      'klllllllllLk', 'kllllllllLLk', '.kLllllllLk.', '..kkLLLLkk..', '....kkkk....', '............'],
    roll: ['............', '............', '..hhhhhhhh..', '.hbbbbbbbbh.', 'hYYYYYYYYYYh', 'hbcbbcbbcbbh',
      'hbcbbcbbcbbh', 'hbbbbbbbbbbh', '.hbbbbbbbbh.', '..hhhhhhhh..', '............', '............'],
  };
  const SLOT_COL = { k: '#181820', r: '#c82828', R: '#f07858', y: '#f8e070', o: '#f0b030', n: '#a86818', g: '#2c8a30',
    G: '#78c850', l: '#f8e048', L: '#c8a020', w: '#f8f8f8', h: '#6a3c10', b: '#e8b048', c: '#c07828', Y: '#f8e098' };
  // At double resolution the reel symbols are smooth: paths on a 24 x 24 grid, drawn once for
  // each size, with their outer edge made crisp afterwards so they sit with the rest.
  const SLOT_PAINT = {
    7(c) {
      const seven = () => { c.beginPath(); c.moveTo(1.5, 1.5); c.lineTo(22.5, 1.5); c.lineTo(22.5, 7); c.lineTo(13.5, 22.5); c.lineTo(5.5, 22.5); c.lineTo(13.5, 7.5); c.lineTo(1.5, 7.5); c.closePath(); };
      seven(); c.lineWidth = 2.5; c.strokeStyle = '#181820'; c.stroke(); c.fillStyle = '#c82828'; c.fill();
      c.fillStyle = '#f07858'; c.fillRect(2.5, 2.5, 19, 1.5);
      c.fillStyle = '#8a1a14'; c.beginPath(); c.moveTo(21.5, 7); c.lineTo(21.5, 5.5); c.lineTo(12.5, 21.5); c.lineTo(11, 21.5); c.closePath(); c.fill();
    },
    bell(c) {
      c.fillStyle = '#181820'; c.beginPath(); c.arc(12, 21.2, 2.4, 0, 7); c.fill();
      const bell = () => { c.beginPath(); c.moveTo(12, 1.5); c.bezierCurveTo(7, 1.5, 6.5, 6, 6, 10); c.bezierCurveTo(5.5, 14, 4, 16, 2, 18.5); c.lineTo(22, 18.5); c.bezierCurveTo(20, 16, 18.5, 14, 18, 10); c.bezierCurveTo(17.5, 6, 17, 1.5, 12, 1.5); c.closePath(); };
      bell(); c.lineWidth = 2; c.strokeStyle = '#181820'; c.stroke(); c.fillStyle = '#f0b030'; c.fill();
      c.fillStyle = '#a86818'; c.beginPath(); c.moveTo(17, 5); c.bezierCurveTo(17.5, 9, 17.5, 14, 21, 18.5); c.lineTo(15, 18.5); c.bezierCurveTo(15, 13, 15, 8, 14, 3); c.closePath(); c.fill();
      c.fillStyle = '#f8e070'; c.beginPath(); c.moveTo(9.5, 3.5); c.bezierCurveTo(8, 7, 8.5, 12, 6, 16.5); c.lineTo(9, 16.5); c.bezierCurveTo(10.5, 12, 10, 7, 11, 3.5); c.closePath(); c.fill();
      c.fillStyle = '#181820'; c.fillRect(2, 18, 20, 1.5); c.fillStyle = '#c88820'; c.fillRect(3.5, 19.5, 17, 1);
    },
    cherry(c) {
      c.strokeStyle = '#2c8a30'; c.lineWidth = 1.2;
      c.beginPath(); c.moveTo(7, 12); c.quadraticCurveTo(9, 6, 17.5, 2); c.stroke();
      c.beginPath(); c.moveTo(17, 12); c.quadraticCurveTo(17, 6, 17.5, 2); c.stroke();
      c.fillStyle = '#78c850'; c.beginPath(); c.moveTo(17, 2); c.quadraticCurveTo(21, 0, 23.5, 3.5); c.quadraticCurveTo(20, 5.5, 17, 2); c.fill();
      for (const x of [6.5, 17.5]) {
        c.fillStyle = '#181820'; c.beginPath(); c.arc(x, 16.5, 6.2, 0, 7); c.fill();
        c.fillStyle = '#8a1a14'; c.beginPath(); c.arc(x, 16.5, 5.2, 0, 7); c.fill();
        c.fillStyle = '#c82828'; c.beginPath(); c.arc(x - 0.6, 16, 4.4, 0, 7); c.fill();
        c.fillStyle = '#f8b0a0'; c.beginPath(); c.ellipse(x - 2, 14, 1.3, 1, -0.6, 0, 7); c.fill();
      }
    },
    lemon(c) {
      const lemon = () => { c.beginPath(); c.moveTo(0.8, 12); c.quadraticCurveTo(3, 11, 4, 8); c.bezierCurveTo(7, 3, 17, 3, 20, 8); c.quadraticCurveTo(21, 11, 23.2, 12); c.quadraticCurveTo(21, 13, 20, 16); c.bezierCurveTo(17, 21, 7, 21, 4, 16); c.quadraticCurveTo(3, 13, 0.8, 12); c.closePath(); };
      lemon(); c.lineWidth = 2; c.strokeStyle = '#181820'; c.stroke(); c.fillStyle = '#f8e048'; c.fill();
      c.fillStyle = '#c8a020'; c.beginPath(); c.moveTo(20, 9); c.quadraticCurveTo(20.5, 11, 22, 12); c.quadraticCurveTo(20, 13, 19.5, 15.5); c.bezierCurveTo(16.5, 19.5, 11, 20, 7, 18.5); c.bezierCurveTo(12, 19, 19, 16, 20, 9); c.fill();
      c.fillStyle = '#fff8c0'; c.beginPath(); c.ellipse(9, 8.5, 3, 1.4, -0.4, 0, 7); c.fill();
    },
    roll(c) {
      c.fillStyle = '#6a3c10'; c.beginPath(); rrPath(c, 0.8, 6.5, 22.4, 12, 5); c.fill();
      c.fillStyle = '#e8b048'; c.beginPath(); rrPath(c, 2, 7.7, 20, 9.6, 4); c.fill();
      c.fillStyle = '#f8e098'; c.fillRect(4.5, 8.5, 15, 2);
      c.fillStyle = '#c07828'; c.fillRect(4.5, 15, 15, 1.5);
      c.strokeStyle = '#c07828'; c.lineWidth = 1;
      for (const x of [7.5, 12, 16.5]) { c.beginPath(); c.moveTo(x, 8.5); c.quadraticCurveTo(x + 1.6, 12, x, 16); c.stroke(); }
    },
  };
  // an alpha over half is solid and the rest is gone, so a picture has crisp edges
  function crispEdges(c, w, h) {
    const im = c.getImageData(0, 0, w, h), d = im.data;
    for (let i = 3; i < d.length; i += 4) d[i] = d[i] > 127 ? 255 : 0;
    c.putImageData(im, 0, 0);
  }
  // a reel symbol, 12 pixels square at scale k
  function drawSlotSymbol(sym, x, y, k) {
    if (sym !== 'bar') {
      ctx.drawImage(finePic('slot' + sym + k, 24 * k, 24 * k, (c) => { c.scale(k, k); SLOT_PAINT[sym](c); crispEdges(c, 24 * k, 24 * k); }), x, y);
      return;
    }
    if (sym === 'bar') {
      // a black plate edged in white, its corners rounded
      roundBox(x, y + 3 * k, 12 * k, 6 * k, 1.5, '#181820');
      if (k > 1) { fine(x + 2, y + 3 * k + 1, 12 * k - 4, 0.5, '#f8f8f8'); fine(x + 2, y + 9 * k - 1.5, 12 * k - 4, 0.5, '#f8f8f8'); fine(x + 1, y + 3 * k + 2, 0.5, 6 * k - 4, '#f8f8f8'); fine(x + 12 * k - 1.5, y + 3 * k + 2, 0.5, 6 * k - 4, '#f8f8f8'); text('BAR', x + 4, y + 9, 1, '#f8f8f8'); }
      else fine(x + 2, y + 5.5, 8, 1, '#f8f8f8');
      return;
    }
    SLOT_PIX[sym].forEach((row, j) => {
      for (let i = 0; i < 12; i++) {
        if (row[i] === '.') continue;
        ctx.fillStyle = SLOT_COL[row[i]]; ctx.fillRect(x + i * k, y + j * k, k, k);
      }
    });
  }

  function SlotsGame() {
    const START = 200, GOAL = 1000, BETS = [5, 10, 25, 50, 100], N = SLOT_STRIP.length;
    const SPEED = 0.45; // stops a frame while a reel spins
    // the reel window: three reels side by side, three symbols tall, the payline through the middle
    const RX = 72, RY = 48, RW = 52, GAP = 6, CELL = 32;
    const CREDITS = [98, 162], SLOT = [160, 96];
    let stack = START, betI = 1, wager = 0, won = 0, state = 'idle', t = 0, record = false, pull = 0, flash = 0;
    let lines = ['Welcome to Spring Roll Slots!', 'Three in a row on the line pays.'];
    // pos: the stop showing on the payline (fractional while it spins); stopAt: where it lands
    const reels = [0, 1, 2].map(() => ({ pos: Math.floor(Math.random() * N), stopAt: null, at: 0, bounce: 0 }));
    const rolls = RollFlyer(), count = (amt) => Math.min(6, 1 + Math.floor(amt / 20));
    const bet = () => Math.min(BETS[betI], stack);
    const showing = (r) => SLOT_STRIP[((Math.round(r.pos) % N) + N) % N];

    function spin() {
      wager = bet(); stack -= wager; won = 0;
      rolls.send(CREDITS[0], CREDITS[1], SLOT[0], SLOT[1], count(wager));
      state = 'spin'; t = 0; pull = 20; sfx('menu');
      lines = ['You bet ' + wager + '. Round and round they go...'];
      // they stop by themselves, one after another, unless you stop them first
      reels.forEach((r, i) => Object.assign(r, { stopAt: null, at: 40 + i * 20 }));
    }
    // Pick where a reel lands, and put it a couple of stops short of there to roll in
    // (it's spinning far too fast to see the jump).
    function stopReel(r) {
      r.stopAt = N + Math.floor(Math.random() * N);
      r.pos = r.stopAt - 2.5;
    }
    function settle() {
      const [a, b, c] = reels.map(showing), cherries = [a, b, c].filter((s) => s === 'cherry').length;
      const jackpot = a === '7' && b === '7' && c === '7';
      let k = 0, msg;
      if (a === b && b === c) { k = SLOT_PAYS[a]; msg = (jackpot ? 'JACKPOT! ' : '') + 'Three ' + SLOT_NAMES[a] + '!'; }
      else if (cherries === 2) { k = 4; msg = 'Two cherries!'; }
      else if (a === 'cherry') { k = 1; msg = 'A cherry on the left.'; }
      won = wager * k; stack += won;
      reels.forEach((r) => { r.pos %= N; r.stopAt = null; });
      if (k > 1) {
        msg += ' You win ' + won + '.';
        rolls.send(SLOT[0], SLOT[1] + 20, CREDITS[0], CREDITS[1], count(won));
        flash = jackpot ? 150 : 60;
        sfx(jackpot ? 'ding' : 'cup');
      } else if (k === 1) { msg += ' Your ' + wager + ' back.'; rolls.send(SLOT[0], SLOT[1] + 20, CREDITS[0], CREDITS[1], count(won)); sfx('blip'); }
      else { msg = 'No luck. You lose ' + wager + '.'; sfx('bump'); }
      lines = [msg, stack ? 'You have ' + stack + ' spring rolls.' : 'That was your last spring roll.'];
      wager = 0;
      if (stack >= GOAL) { state = 'over'; t = 0; record = saveBest('slots', stack); return; }
      state = stack > 0 ? 'idle' : 'broke';
    }
    function leave() {
      // walking away mid-spin forfeits the bet
      if (state !== 'over') record = saveBest('slots', stack);
      remove(self);
      if (state === 'over') { say('You cleaned out the slot machine. Cody unplugs it, just in case.'); return; }
      say('You cash out with ' + stack + ' spring rolls.' + (record ? ' A new record!' : ''));
    }
    const askLeave = () => ask('Cash out with ' + stack + ' spring rolls?', ['CASH OUT', 'KEEP PLAYING'], (i) => { if (i === 0) leave(); });

    const self = {
      music: 'poker', doing: 'slots',
      update() {
        t++;
        rolls.update();
        if (pull > 0) pull--;
        if (flash > 0) flash--;
        if (state === 'over') { if (t > 30 && (pressed.has('a') || pressed.has('b'))) leave(); return; }
        if (state === 'broke') {
          if (pressed.has('a') || pressed.has('b')) { remove(self); say("Cody: The machine always wins. Trust me, I've checked."); }
          return;
        }
        if (pressed.has('b')) { askLeave(); return; }
        if (state === 'spin') {
          // A stops the next reel along
          const next = reels.find((r) => r.stopAt === null);
          if (next && pressed.has('a')) stopReel(next);
          for (const r of reels) {
            if (r.bounce > 0) r.bounce--;
            if (r.stopAt === null) { r.pos = (r.pos + SPEED) % N; if (t >= r.at) stopReel(r); }
            else if (r.pos < r.stopAt) {
              r.pos = Math.min(r.stopAt, r.pos + SPEED);
              if (r.pos === r.stopAt) { r.bounce = 8; sfx('putt'); }
            }
          }
          if (reels.every((r) => r.stopAt !== null && r.pos === r.stopAt && !r.bounce)) settle();
          return;
        }
        const nudge = (d) => {
          const i = Math.max(0, Math.min(BETS.length - 1, betI + d));
          if (i !== betI && (d < 0 || BETS[betI] < stack)) { betI = i; sfx('select'); }
        };
        if (pressed.has('right') || pressed.has('up')) nudge(1);
        if (pressed.has('left') || pressed.has('down')) nudge(-1);
        if (pressed.has('a')) spin();
      },
      draw() {
        const blink = (tick >> (flash ? 2 : 4)) & 1;
        ctx.fillStyle = '#140a10'; ctx.fillRect(0, 0, SW, SH);
        // the machines either side of this one, in the dark
        for (const x of [-26, 298]) {
          ctx.fillStyle = '#3a0c10'; ctx.fillRect(x, 14, 48, 188);
          ctx.fillStyle = '#1c0e08'; ctx.fillRect(x + 6, 60, 36, 50);
          fine(x, 14, 48, 0.5, '#5a1c20'); fine(x + 6, 60, 36, 0.5, '#2c1c14'); fine(x + 6, 109.5, 36, 0.5, '#4a1418');
        }
        // the cabinet
        ctx.fillStyle = INK; ctx.fillRect(44, 2, 224, 200);
        ctx.fillStyle = '#a82020'; ctx.fillRect(45, 3, 222, 198);
        ctx.fillStyle = '#7a1414'; ctx.fillRect(45, 3, 5, 198); ctx.fillRect(262, 3, 5, 198);
        // the paint's shine, chrome trim down each side, and the cabinet's seams and screws
        fine(50, 3, 212, 0.5, '#e05048'); fine(50, 3.5, 0.5, 197.5, '#d04038'); fine(261.5, 3.5, 0.5, 197.5, '#801818');
        for (const tx of [45, 262]) { fine(tx + 1, 3, 3, 198, '#8a1a18'); fine(tx + 1, 3, 1, 198, '#c04038'); fine(tx + 3.5, 3, 0.5, 198, '#5a0c0c'); for (let y = 12; y < 198; y += 44) { fineDisc(tx + 2.5, y, 1, '#d8dce8'); fine(tx + 2, y, 1, 0.5, '#585868'); } }
        fine(50, 145.5, 212, 0.5, '#801818'); fine(50, 146, 212, 0.5, '#d04038');
        // the marquee, with bulbs chasing round it (all of them flashing when you win)
        ctx.fillStyle = INK; ctx.fillRect(56, 7, 200, 33);
        ctx.fillStyle = '#1c0e08'; ctx.fillRect(57, 8, 198, 31);
        fine(56, 7, 200, 0.5, '#585868'); fine(57, 8, 198, 1, '#100804');
        let n = 0;
        const bulb = (x, y) => {
          const lit = flash ? blink : ((n++ + (tick >> 3)) % 3 === 0);
          // round, with a glow when lit
          if (lit) fineDisc(x + 1, y + 1, 2, 'rgba(248, 240, 176, 0.3)');
          fineDisc(x + 1, y + 1, 1.25, lit ? '#f8f0b0' : '#a86818'); fine(x + 0.5, y + 0.5, 0.5, 0.5, lit ? '#ffffff' : '#d8a848');
        };
        for (let x = 59; x < 253; x += 6) bulb(x, 9);
        for (let y = 15; y < 36; y += 6) bulb(252, y);
        for (let x = 253; x > 58; x -= 6) bulb(x, 36);
        for (let y = 30; y > 12; y -= 6) bulb(58, y);
        text('SPRING ROLL', 160 - 33, 13, 1, BRASS);
        text('SLOTS', 160 - 30, 22, 2, flash && blink ? '#f8f8f8' : '#f05040');
        // the reels behind their window, with the payline across the middle
        ctx.fillStyle = INK; ctx.fillRect(RX - 6, RY - 4, 3 * RW + 2 * GAP + 12, 3 * CELL + 8);
        ctx.fillStyle = BRASS; ring(RX - 5, RY - 3, 3 * RW + 2 * GAP + 10, 3 * CELL + 6);
        fine(RX - 5, RY - 3, 3 * RW + 2 * GAP + 10, 0.5, '#f8e8a8'); fine(RX - 5, RY - 3, 0.5, 3 * CELL + 6, '#f8e8a8'); fine(RX - 5, RY + 3 * CELL + 2.5, 3 * RW + 2 * GAP + 10, 0.5, '#a88030'); fine(RX + 3 * RW + 2 * GAP + 4.5, RY - 3, 0.5, 3 * CELL + 6, '#a88030');
        reels.forEach((r, i) => {
          const x = RX + i * (RW + GAP);
          ctx.save();
          ctx.beginPath(); ctx.rect(x, RY, RW, 3 * CELL); ctx.clip();
          ctx.fillStyle = '#f4f0e4'; ctx.fillRect(x, RY, RW, 3 * CELL);
          const off = Math.round(Math.sin((r.bounce / 8) * Math.PI) * 4), base = Math.floor(r.pos);
          for (let d = -2; d <= 2; d++) {
            const j = base + d, y = RY + CELL + Math.round((r.pos - j) * CELL) + off;
            drawSlotSymbol(SLOT_STRIP[((j % N) + N) % N], x + (RW >> 1) - 12, y + 4, 2);
          }
          // the reel curving away at the top and bottom
          // (a smooth fall into the shade, and the glass's gleam)
          for (let d = 0; d < 14; d += 0.5) { const a = 'rgba(24,24,32,' + (0.32 * (1 - d / 14) ** 1.5).toFixed(3) + ')'; fine(x, RY + d, RW, 0.5, a); fine(x, RY + 3 * CELL - d - 0.5, RW, 0.5, a); }
          fine(x + 3, RY + 4, 2, 3 * CELL - 8, 'rgba(255,255,255,0.28)'); fine(x + 6, RY + 4, 0.5, 3 * CELL - 8, 'rgba(255,255,255,0.28)'); fine(x + RW - 1, RY, 1, 3 * CELL, 'rgba(24,24,32,0.14)');
          ctx.restore();
        });
        const ly = RY + CELL + (CELL >> 1);
        ctx.fillStyle = 'rgba(200,40,40,0.55)'; ctx.fillRect(RX - 2, ly, 3 * RW + 2 * GAP + 4, 0.5);
        ctx.fillStyle = '#f05040';
        for (let k = 0; k < 4; k += 0.5) { fine(RX - 10 + k, ly - 3.5 + k, 0.5, 8 - 2 * k, '#f05040'); fine(RX + 3 * RW + 2 * GAP + 9.5 - k, ly - 3.5 + k, 0.5, 8 - 2 * k, '#f05040'); }
        // credits, bet and winnings, in red lights
        [['CREDITS', stack, 66, 64], ['BET', state === 'spin' ? wager : bet(), 138, 44], ['WIN', won, 190, 56]].forEach(([l, v, x, w]) => {
          text(l, x, 150, 1, '#f8e070');
          ctx.fillStyle = INK; ctx.fillRect(x, 158, w, 13);
          fine(x, 158, w, 1, '#080810'); fine(x, 170.5, w, 0.5, '#f05050'); fine(x, 159, 0.5, 12, '#080810');
          const s = String(v);
          if (l !== 'WIN' || !flash || blink) text(s, x + w - 3 - s.length * 6, 161, 1, '#ff4830');
        });
        // what pays
        const pays = [[['7', '7', '7'], 100], [['bar', 'bar', 'bar'], 40], [['bell', 'bell', 'bell'], 20], [['roll', 'roll', 'roll'], 12],
          [['cherry', 'cherry', 'cherry'], 10], [['lemon', 'lemon', 'lemon'], 5], [['cherry', 'cherry'], 4], [['cherry'], 1]];
        ctx.fillStyle = '#7a1414'; ctx.fillRect(54, 174, 204, 26);
        fine(54, 174, 204, 0.5, '#4a0c0c'); fine(54, 174, 0.5, 26, '#4a0c0c'); fine(54, 199.5, 204, 0.5, '#c04038'); fine(257.5, 174, 0.5, 26, '#c04038');
        pays.forEach(([syms, k], i) => {
          const x = 58 + (i % 4) * 50, y = 175 + (i >> 2) * 12;
          syms.forEach((sy, j) => drawSlotSymbol(sy, x + j * 8, y, 1));
          text(String(k), x + 28, y + 3, 1, '#f8e070');
        });
        // the lever: pull it and the knob swings down and back up
        const ky = 62 + Math.round(Math.sin(((20 - pull) / 20) * Math.PI) * (pull ? 52 : 0));
        ctx.fillStyle = INK; ctx.fillRect(267, 104, 10, 22); ctx.fillRect(280, Math.min(ky, 114), 5, Math.abs(114 - ky) + 1);
        ctx.fillStyle = '#585868'; ctx.fillRect(268, 105, 8, 20);
        ctx.fillStyle = '#c8ccd8'; ctx.fillRect(281, Math.min(ky, 114), 3, Math.abs(114 - ky));
        ctx.fillStyle = INK; ctx.fillRect(276, 113, 9, 4);
        // the housing's bevel and bolts, a chrome shaft, and a shining ball on top
        fine(268, 105, 8, 0.5, '#888898'); fine(268, 105, 0.5, 20, '#888898'); fine(275.5, 105.5, 0.5, 19.5, '#383848');
        for (const y of [108, 121]) { fineDisc(272, y, 1, '#a8acb8'); fine(271.5, y, 1, 0.5, '#383848'); }
        fine(281, Math.min(ky, 114), 1, Math.abs(114 - ky), '#f8f8f8'); fine(283, Math.min(ky, 114), 1, Math.abs(114 - ky), '#8890a0');
        fine(276.5, 113.5, 8, 1, '#888898');
        fineDisc(282.5, ky - 0.5, 6.5, INK); fineDisc(282.5, ky - 0.5, 5.5, '#a82020'); fineDisc(282, ky - 1, 4.5, '#d83030'); fineDisc(280.5, ky - 2.5, 1.75, '#f8a8a0'); fine(280, ky - 3, 1, 0.5, '#ffffff');
        rolls.draw();
        // what just happened, and what to press
        ctx.fillStyle = BRASS; ctx.fillRect(4, 205, SW - 8, 24);
        ctx.fillStyle = '#1c0e08'; ctx.fillRect(5, 206, SW - 10, 22);
        fine(4, 205, SW - 8, 0.5, '#f8e8a8'); fine(4, 228.5, SW - 8, 0.5, '#a88030'); fine(5, 206, SW - 10, 1, '#0c0604'); fine(5, 207, 0.5, 21, '#0c0604');
        lines.slice(0, 2).forEach((l, i) => text(l, 10, 208 + i * 10, 1, CREAM));
        const hint = state === 'spin' ? 'Space: stop a reel  Esc: cash out'
          : state === 'broke' ? 'Space: leave' : 'Arrows: bet  Space: spin  Esc: cash out';
        if (state !== 'over') text(hint, 10, 232, 1, '#c8a878');
        if (state === 'over') doneBox(['You cleaned out the machine!',
          'Spring rolls: ' + stack, record ? 'New record!' : 'Best ' + getBest('slots')], t);
      },
    };
    return self;
  }

  // ---------- coffee mini-game: move the cup to catch falling coffee ----------
  // Against a player (vs) you both get the same pour, and their cup is a faint outline
  // chasing the same drops.
  let coffeesToday = 0;
  function CoffeeGame(vs) {
    const AX = 12, AW = 248, HEAD = 18, CUP_Y = 184, CUP_W = 44, CUP_H = 34, FLOOR = 220;
    const COFFEE = '#6b3a1e', CREMA = '#b07040';
    const METER = { x: 280, y: 40, w: 24, h: 168 };
    // the machine pours this many drops and stops; your score is how many land in the cup
    const DROPS = 150;
    let cup = AX + AW / 2 - CUP_W / 2, fill = 0, caught = 0, missed = 0, t = 0, state = 'ready';
    let poured = 0, wait = 0, record = false, frame = 0;
    let nozzle = AX + AW / 2, target = nozzle, drops = [], splashes = [];
    const rnd = vs ? vs.rng : Math.random, ghost = ghostTrack();
    const race = vs && scoreRace(vs, { what: 'the coffee machine', fmt: String, hear: (m) => ghost.add(m) });
    const self = {
      music: 'coffee', doing: 'coffee',
      update() {
        t++;
        if (race) {
          if (race.update() && state !== 'over') { state = 'over'; t = 0; sfx(race.outcome === 'win' ? 'cup' : 'bump'); }
          if (state === 'over') { if (t > 30 && (pressed.has('a') || pressed.has('b'))) { remove(self); vs.end(); race.say(); } return; }
          if (state === 'wait') { if (pressed.has('b')) { remove(self); vs.end(); say('You leave the coffee machine.'); } return; }
        }
        if (state === 'ready') { if (t > 75) { state = 'play'; t = 0; } return; }
        if (state === 'done') {
          if (t > 30 && (pressed.has('a') || pressed.has('b'))) {
            remove(self);
            coffeesToday++;
            say(coffeesToday === 1
              ? 'You made a cup of coffee. Ahh, that hits the spot!'
              : 'Another cup of coffee! That\'s ' + coffeesToday + ' today...');
          }
          return;
        }
        if (pressed.has('b')) { remove(self); if (vs) vs.end(); say('You leave the coffee for later.'); return; }
        frame++;
        if (held.left) cup = Math.max(AX, cup - 3);
        if (held.right) cup = Math.min(AX + AW - CUP_W, cup + 3);
        if (race) { race.send({ f: frame, x: Math.round(cup), s: caught }, Math.round(cup) + ':' + caught); ghost.follow(frame); }
        // the nozzle wanders back and forth. As the pour goes on it gets faster (in the end
        // faster than the cup), drips more often and starts changing its mind halfway.
        const p = poured / DROPS;
        if (Math.abs(target - nozzle) < 2 || rnd() < 0.025 * p) target = AX + 12 + rnd() * (AW - 24);
        nozzle += Math.sign(target - nozzle) * Math.min(Math.abs(target - nozzle), 1.2 + 4.4 * p);
        if (poured < DROPS && --wait <= 0) {
          drops.push({ x: nozzle - 1 + (rnd() * 4 - 2), y: HEAD + 22, vy: 1 });
          poured++; wait = Math.round(8 - 3 * p);
        }
        for (const d of drops) { d.vy = Math.min(d.vy + 0.08, 4); d.y += d.vy; }
        drops = drops.filter((d) => {
          if (d.y + 6 >= CUP_Y && d.y < CUP_Y + 8 && d.x + 3 > cup + 3 && d.x < cup + CUP_W - 3) {
            caught++; fill = 100 * caught / DROPS;
            sfx('pour', fill);
            splashes.push({ x: d.x, y: CUP_Y + 2, t: 0 });
            return false;
          }
          if (d.y > FLOOR - 4) { missed++; splashes.push({ x: d.x, y: FLOOR - 2, t: 0 }); return false; }
          return true;
        });
        splashes.forEach((sp) => sp.t++);
        splashes = splashes.filter((sp) => sp.t < 12);
        if (poured >= DROPS && !drops.length) {
          if (race) { race.finish(caught); state = 'wait'; t = 0; return; }
          state = 'done'; t = 0; record = saveBest('coffee', caught); sfx('ding');
        }
      },
      draw() {
        box(0, 0, SW, SH);
        text('Catch the coffee!', AX + 4, 6);
        const b = race ? vs.name + ' ' + race.now : 'Best ' + getBest('coffee');
        text(b, AX + AW - b.length * 6, 6);
        // machine head + nozzle
        ctx.fillStyle = col.dark; ctx.fillRect(AX, HEAD, AW, 14);
        ctx.fillStyle = '#585868'; ctx.fillRect(AX + 1, HEAD + 1, AW - 2, 12);
        ctx.fillStyle = col.dark; ctx.fillRect(Math.round(nozzle) - 6, HEAD + 13, 12, 8);
        ctx.fillStyle = '#8890a0'; ctx.fillRect(Math.round(nozzle) - 5, HEAD + 14, 10, 6);
        // a chrome trim and vents along the head, a little light, the nozzle's shine and lip
        fine(AX + 1, HEAD + 1, AW - 2, 0.5, '#8890a0'); fine(AX + 1, HEAD + 12.5, AW - 2, 0.5, '#383848');
        for (let vx = AX + 8; vx < AX + AW - 20; vx += 5) fine(vx, HEAD + 5, 3, 0.5, '#383848');
        fine(AX + AW - 12, HEAD + 5, 2, 2, '#48d860'); fine(AX + AW - 12, HEAD + 5, 1, 1, '#c8ffc8');
        const nx = Math.round(nozzle);
        fine(nx - 5, HEAD + 14, 0.5, 6, '#c8ccd8'); fine(nx - 2, HEAD + 14, 0.5, 6, '#a8b0c0'); fine(nx - 5, HEAD + 19.5, 10, 0.5, '#585868');
        if (state === 'play' && poured < DROPS) { ctx.fillStyle = COFFEE; ctx.fillRect(Math.round(nozzle) - 1, HEAD + 21, 2, 3); }
        // falling coffee
        for (const d of drops) {
          const dx = Math.round(d.x), dy = Math.round(d.y);
          // a rounded drop with a glint
          fine(dx + 0.5, dy, 2, 0.5, COFFEE); fine(dx, dy + 0.5, 3, 5, COFFEE); fine(dx + 0.5, dy + 5.5, 2, 0.5, COFFEE);
          fine(dx + 0.5, dy + 1, 0.5, 1.5, CREMA);
        }
        // counter
        ctx.fillStyle = col.dark; ctx.fillRect(AX, FLOOR, AW, 1);
        ctx.fillStyle = '#c8ccd8'; ctx.fillRect(AX, FLOOR + 1, AW, 5);
        fine(AX, FLOOR + 1, AW, 0.5, '#f8f8f8'); fine(AX, FLOOR + 5.5, AW, 0.5, '#a8b0c0'); for (let i = AX + 6; i < AX + AW; i += 23) fine(i, FLOOR + 2, 4, 0.5, '#e4e4ec');
        // their cup: an outline where it was at this point in the pour, until they're done
        if (race && ghost.started && !(race.theirsDone && frame - ghost.lag > ghost.end)) {
          const gx = Math.round(ghost.at(frame - ghost.lag, 'x'));
          ctx.globalAlpha = 0.45; ctx.fillStyle = col.dark;
          ring(gx, CUP_Y, CUP_W, CUP_H); ring(gx + 1, CUP_Y + 1, CUP_W - 2, CUP_H - 2);
          ctx.fillRect(gx + CUP_W, CUP_Y + 8, 6, 2); ctx.fillRect(gx + CUP_W + 5, CUP_Y + 8, 2, 16); ctx.fillRect(gx + CUP_W, CUP_Y + 22, 6, 2);
          const n = vs.name.slice(0, 7);
          text(n, gx + ((CUP_W - n.length * 6) >> 1), CUP_Y + 15, 1, col.dark);
          ctx.globalAlpha = 1;
        }
        // cup, filling up as you catch coffee
        const cx0 = Math.round(cup), inner = CUP_H - 4, lvl = Math.round(inner * fill / 100);
        ctx.fillStyle = col.dark; ctx.fillRect(cx0, CUP_Y, CUP_W, CUP_H);
        ctx.fillRect(cx0 + CUP_W, CUP_Y + 8, 7, 16);
        ctx.fillStyle = col.light; ctx.fillRect(cx0 + CUP_W, CUP_Y + 11, 4, 10);
        ctx.fillStyle = '#f8f8f8'; ctx.fillRect(cx0 + 2, CUP_Y + 2, CUP_W - 4, CUP_H - 4);
        ctx.fillStyle = COFFEE; ctx.fillRect(cx0 + 2, CUP_Y + 2 + inner - lvl, CUP_W - 4, lvl);
        if (lvl) { ctx.fillStyle = CREMA; ctx.fillRect(cx0 + 2, CUP_Y + 2 + inner - lvl, CUP_W - 4, 1); }
        // name on a sleeve around the cup
        ctx.fillStyle = col.dark; ctx.fillRect(cx0, CUP_Y + 12, CUP_W, 13);
        ctx.fillStyle = '#e8d4b0'; ctx.fillRect(cx0 + 1, CUP_Y + 13, CUP_W - 2, 11);
        text('Haakon', cx0 + 4, CUP_Y + 15, 1, '#5a3420');
        // a shine down the cup, the shade on its far side, the sleeve's corrugations, the crema's swirl
        fine(cx0 + 3, CUP_Y + 2, 1, 10, '#ffffff'); fine(cx0 + CUP_W - 3.5, CUP_Y + 2, 1, CUP_H - 4, '#e4e4ec');
        for (let i = 1; i < 11; i += 2) { fine(cx0 + 1, CUP_Y + 13 + i, 0.5, 0.5, '#c8b090'); fine(cx0 + CUP_W - 1.5, CUP_Y + 13 + i, 0.5, 0.5, '#c8b090'); }
        if (lvl > 1) { const sy = CUP_Y + 2 + inner - lvl; fine(cx0 + 6, sy + 0.5, 6, 0.5, '#e8c890'); fine(cx0 + 14, sy + 0.5, 3, 0.5, '#e8c890'); }
        fine(cx0 + CUP_W + 1, CUP_Y + 11, 0.5, 10, '#ffffff');
        // splashes
        for (const sp of splashes) {
          ctx.fillStyle = COFFEE;
          const dx = 2 + sp.t, dy = Math.round(sp.t * 0.8) - Math.round(sp.t * sp.t * 0.06);
          const sz = 1.5;
          ctx.fillRect(Math.round(sp.x) - dx, sp.y - dy, sz, sz);
          ctx.fillRect(Math.round(sp.x) + dx, sp.y - dy, sz, sz);
        }
        // fill meter
        const m = METER, mh = Math.round((m.h - 4) * fill / 100);
        text('FILL', m.x, m.y - 12);
        ctx.fillStyle = col.dark; ctx.fillRect(m.x, m.y, m.w, m.h);
        ctx.fillStyle = col.light; ctx.fillRect(m.x + 2, m.y + 2, m.w - 4, m.h - 4);
        ctx.fillStyle = COFFEE; ctx.fillRect(m.x + 2, m.y + m.h - 2 - mh, m.w - 4, mh);
        ctx.fillStyle = CREMA;
        for (let yy = m.y + m.h - 2 - mh; yy < m.y + m.h - 2; yy += 8) ctx.fillRect(m.x + 2, yy, m.w - 4, 0.5);
        // marks every tenth, a shine down the glass
        for (let k = 1; k < 10; k++) fine(m.x + 2, m.y + 2 + Math.round((m.h - 4) * k / 10), k % 5 ? 2 : 4, 0.5, '#181820');
        fine(m.x + m.w - 4, m.y + 2, 1, m.h - 4, 'rgba(255, 255, 255, 0.5)');
        text(Math.floor(fill) + '%', m.x, m.y + m.h + 4);
        // how full their cup is, as a notch beside the meter
        if (race) {
          const ty = m.y + m.h - 2 - Math.round((m.h - 4) * Math.min(1, race.now / DROPS));
          ctx.fillStyle = col.dark; ctx.fillRect(m.x - 5, ty - 1, 5, 3);
        }
        // messages
        if (state === 'ready') {
          box(70, 92, 180, 48);
          text(t < 50 ? 'Get ready...' : 'GO!', 70 + (t < 50 ? 54 : 81), 104);
          text('Left/Right: move cup', 70 + 30, 120);
        } else if (state === 'over') race.box(t);
        else if (state === 'wait') race.waitBox();
        else if (state === 'done') {
          doneBox(['Coffee\'s ready!', 'Caught ' + caught + ' of ' + DROPS + '   Spilled ' + missed, record ? 'New record!' : 'Best ' + getBest('coffee')], t);
        } else {
          text('Esc: give up', AX + 4, SH - 16);
        }
      },
    };
    return self;
  }

  // ---------- shared bits for the arcade mini-games ----------
  const ctext = (str, y, color) => {
    if (buttonHints()) str = touchHint(str);
    text(str, (SW - str.length * 6) >> 1, y, 1, color);
  };
  // Save a high score; returns true if it's a new record.
  function saveBest(key, score) {
    questNote(key, score);
    boardNote(key, score);
    if (score <= (+store.get('best.' + key) || 0)) return false;
    store.set('best.' + key, score);
    return true;
  }
  const getBest = (key) => +store.get('best.' + key) || 0;

  // ---------- online leaderboards ----------
  // Everyone's best score at each game, kept in a Firebase Realtime Database (BOARD_URL)
  // as scores/<game>/<name> = { name, score, t }: one row per name. Only the games listed
  // here have a board. A higher stored score is always better, so the fewest-strokes and
  // fastest-time games (low) are stored negated.
  const tenths = (n) => (n / 10).toFixed(1) + 's';
  const racetime = (n) => Math.floor(n / 600) + ':' + ((n % 600) / 10).toFixed(1).padStart(4, '0'); // (tenths of a second, as 1:05.3)
  const times = (n) => n + (n === 1 ? ' time' : ' times');
  const goals = (n) => n + (n === 1 ? ' goal' : ' goals');
  const signed = (n) => (n > 0 ? '+' : '') + n;
  const BOARDS = {
    coffee: { title: 'COFFEE MACHINE' }, punch5: { title: 'PUNCHING BAG' }, run: { title: 'TREADMILL', unit: 'm' }, toss: { title: 'PAPER TOSS' },
    stack: { title: 'PHOTOCOPIER' }, simon: { title: 'CONTROL PANEL' }, lunch: { title: 'FIND MY LUNCH' },
    candy: { title: 'CANDY TABLE' }, squat: { title: 'SQUAT RACK', unit: ' lb' }, fan: { title: 'FAN BALANCING' },
    coil: { title: 'COOLING COIL', unit: 's' }, damper: { title: 'DAMPERS' }, filter: { title: 'FILTER CHANGE' },
    snake: { title: 'SNAKE' }, galaxy: { title: 'GALAXY GUARD' }, pong: { title: 'BEAT THE TV AT PONG', unit: times, count: true }, chess: { title: 'CHESS CHECKMATES', unit: times, count: true }, checkers: { title: 'CHECKERS WINS', unit: times, count: true }, parts: { title: 'PARTS SORTING' }, cable: { title: 'CABLE TIDY' },
    engrave: { title: 'ENGRAVER', unit: '%' }, ball: { title: 'EXERCISE BALL', unit: 's' },
    desk: { title: 'FRONT DESK' }, jam: { title: 'PAPER JAM' }, laundry: { title: 'LAUNDRY' },
    forms: { title: 'JHONNA\'S FORMS' }, trophy: { title: 'NATHAN\'S TROPHIES' }, legolines: { title: 'JOE\'S BRICK BATTLE' },
    legosolo: { title: 'LEGO BUILDING', unit: ' lines' },
    // These six once had a most you could score, so the best players all tied on it: the old
    // boards (cpr, pulldown, wokdishes, carrotpct, dance, costume) were 30 perfect compressions,
    // 20 reps, dishes in a minute, two percentages and 30 from the judges. Now they go on until
    // you've made too many mistakes, or for the wok, count every piece you plate.
    cprpts: { title: 'CPR' }, pullreps: { title: 'LAT PULLDOWN', unit: (n) => n + (n === 1 ? ' rep' : ' reps') },
    wokpieces: { title: 'NIK\'S WOK', unit: (n) => n + (n === 1 ? ' piece' : ' pieces') }, carrotpts: { title: 'DMITRIY\'S CARROTS' },
    dancepts: { title: 'PATRICK\'S DANCE-OFF' }, costumepts: { title: 'COSTUME CONTEST' },
    poker: { title: 'SPRING ROLL HOLD\'EM' }, blackjack: { title: 'SPRING ROLL BLACKJACK' }, slots: { title: 'SPRING ROLL SLOTS' },
    // the live table: spring rolls won less spring rolls lost there, all told (see netNote)
    pokerlive: { title: 'LIVE HOLD\'EM', unit: ' rolls', net: true },
    // most catches in a row (the old `catch` board was out of 10 throws, in an easier game)
    catchrun: { title: 'FRISBEE CATCH' },
    bob: { title: 'BOBBING FOR APPLES' }, carve: { title: 'PUMPKIN CARVING' }, treat: { title: 'TRICK-OR-TREAT' },
    ghosts: { title: 'GHOST IN THE CUPBOARD' },
    // (the old `golf` board was over 5 holes, before you got all 9 on your own)
    golf9: { title: 'WADE\'S PUTTING GREEN', low: true }, dark: { title: 'DAMIR\'S LIGHTS', unit: 's', low: true },
    mummy: { title: 'MUMMY WRAP', unit: tenths, low: true }, humbug: { title: 'HUMBUG SWEEPER', unit: tenths, low: true },
    // Humbug Sweeper over Christmas 2026 only, for the Christmas Cup (CUP): not in the Hall of Fame
    humbug26: { title: 'CHRISTMAS CUP 2026', unit: tenths, low: true, unlisted: true },
    forklift: { title: 'FORKLIFT RUSH', unit: ' pallets' }, paint: { title: 'EVEN COAT' },
    chop: { title: 'WOOD CHOPPING', unit: ' logs' }, mallow: { title: 'MARSHMALLOWS' }, spruce: { title: 'DECK THE SPRUCE' },
    snowman: { title: 'SNOWMAN', unit: ' cm' }, cocoa: { title: 'HOT CHOCOLATE STAND', unit: ' stars' }, snowball: { title: 'SNOWBALL FIGHT', unit: ' hits' },
    // Haakon Grand Prix: your fastest race on each track, three laps against coworkers (RACE_BOARDS)
    racelake: { title: 'LAKESHORE GP', unit: racetime, low: true }, racemaple: { title: 'MAPLE HOLLOW GP', unit: racetime, low: true },
    racesnow: { title: 'SNOWBELT GP', unit: racetime, low: true }, raceprairie: { title: 'CANOLA FLATS GP', unit: racetime, low: true },
    raceplant: { title: 'KINGSTON PLANT GP', unit: racetime, low: true },
    // the most you've scored in one game of hockey against a coworker (played to the end)
    hockey: { title: 'HOCKEY GOALS', unit: goals },
    // Morale Madness: how many cards you have, starter cards and all, and how many times you've beaten another player
    cards: { title: 'CARDS COLLECTED', unit: (n) => n + (n === 1 ? ' card' : ' cards') }, cardwins: { title: 'MORALE MADNESS WINS', unit: times, count: true },
    // the side quests: the "score" is how many times that name has done it (see questBoard), as it is for Pong (count)
    linda: { title: 'LINDA SET FREE', unit: times, quest: true, count: true }, eotm: { title: 'EMPLOYEE OF THE MONTH', unit: times, quest: true, count: true },
  };
  // tools/test.html sets BOARD_DEMO: the boards show made-up rows and nothing is sent
  const boardDemo = !!window.BOARD_DEMO;
  let pendingBoard = null;
  // Called with every result; the board itself goes up once the game on top has closed (see update).
  function boardNote(key, score) {
    lairNote(key, score);
    if (key.startsWith('dogrun.')) key = 'catchrun';
    if (!BOARDS[key] || !(BOARD_URL || boardDemo)) return;
    pendingBoard = { key, score, owner: top() };
  }
  // Linda freed, Employee of the Month won or the TV beaten at Pong: one more time on that
  // board. The count goes up from what the database already holds for the name, so playing
  // on a phone and a computer adds up. The board goes up once everything that was being said is done.
  function questBoard(key) {
    lairNote(key, 1);
    if (!(BOARD_URL || boardDemo)) return;
    const name = playerName || store.get('name') || '';
    const mine = !name || boardDemo || !BOARD_POSTS ? Promise.resolve(null)
      : boardFetch(key + '/' + boardKey(name) + '.json').then((r) => (r.ok ? r.json() : Promise.reject()));
    mine.then((r) => (r && typeof r.score === 'number' ? r.score : 0) + 1, () => 0) // couldn't check: show it, add nothing
      .then((score) => { pendingBoard = { key, score, owner: null, quiet: true }; });
  }
  // A hand at the live poker table is over: n is what you came out of it with, ahead or
  // behind. A net board (pokerlive) keeps each name's spring rolls won and lost there as
  // two plain boards, <key>won and <key>lost, so both only ever go up; like the quests,
  // each goes up from what the database already holds. One send at a time, and the board
  // waits for them (see boardLoad).
  let netSending = Promise.resolve();
  function netNote(key, n) {
    const name = playerName || store.get('name') || '';
    if (!n || !name || !BOARD_URL || !BOARD_POSTS || boardDemo) return;
    const path = key + (n > 0 ? 'won' : 'lost') + '/' + boardKey(name) + '.json';
    netSending = netSending.then(() => boardFetch(path))
      .then((r) => (r.ok ? r.json() : Promise.reject()))
      .then((r) => boardFetch(path, { method: 'PUT', body: JSON.stringify({ name, score: (r && typeof r.score === 'number' ? r.score : 0) + Math.abs(n), t: { '.sv': 'timestamp' } }) }))
      .catch(() => {}); // couldn't check what's there: add nothing
  }
  // a name's row in the database: "Sam" and "sam" are the same person
  const boardKey = (name) => name.toLowerCase().replace(/[^a-z0-9]/g, '_');
  function boardFetch(path, opts) {
    const ac = new AbortController(), timer = setTimeout(() => ac.abort(), 5000);
    return fetch(BOARD_URL.replace(/\/+$/, '') + '/scores/' + path, Object.assign({ signal: ac.signal }, opts))
      .finally(() => clearTimeout(timer));
  }
  const byScore = (a, b) => b.score - a.score || a.t - b.t;
  const boardSort = (rows) => rows.sort(byScore).slice(0, 10);
  // every row of a board as the database sent it, best first
  const boardRows = (all) => Object.entries(all || {}).filter(([, r]) => r && typeof r.score === 'number')
    .map(([rid, r]) => ({ id: rid, name: String(r.name).slice(0, NAME_MAX), score: r.score, t: +r.t || 0 })).sort(byScore);
  // a stored score (or the gap between two) as the game shows it: "12 pallets", "8.4s"
  function boardFmt(key, v) {
    const b = BOARDS[key], n = b.low ? -v : v;
    return typeof b.unit === 'function' ? b.unit(n) : n + (b.unit || '');
  }
  const DEMO_NAMES = ['Ada', 'Grace', 'Linus', 'Margaret', 'Dennis', 'Barbara', 'Ken', 'Radia', 'Tim', 'Guido', 'Edsger'];
  // Send the score (the database refuses anything that isn't an improvement on that name's
  // row), then fetch the top ten and the name's own row.
  function boardLoad(key, name, score) {
    const val = BOARDS[key].low ? -score : score, id = boardKey(name), send = name && score > 0 && (BOARD_POSTS || boardDemo);
    // a net board is sent to hand by hand (netNote), and can only be put in order once it's all here
    if (BOARDS[key].net) {
      return netSending.then(() => boardAll(key, name))
        .then((rows) => ({ rows: rows.slice(0, 10), mine: rows.find((r) => r.id === id) || null }));
    }
    if (boardDemo) {
      const rows = DEMO_NAMES.map((n, i) => ({ id: boardKey(n), name: n, score: BOARDS[key].low ? -(20 + i * 3) : BOARDS[key].count ? Math.max(1, 7 - i) : 100 - i * 7, t: i }));
      const mine = send ? { name, score: val } : null;
      if (mine) rows.push({ id, name, score: val, t: 99 });
      return Promise.resolve({ rows: boardSort(rows), mine });
    }
    return (send ? boardSend(key, name, score) : Promise.resolve()).then(() => Promise.all([
      boardFetch(key + '.json?orderBy=%22score%22&limitToLast=10'),
      name ? boardFetch(key + '/' + id + '.json') : null,
    ])).then(([all, mine]) => {
      if (!all.ok) throw new Error('board ' + all.status);
      return Promise.all([all.json(), mine && mine.ok ? mine.json() : null]);
    }).then(([all, mine]) => ({
      rows: boardRows(all).slice(0, 10),
      mine: mine && typeof mine.score === 'number' ? mine : null,
    }));
  }
  // Send a name's score to a board, with no board to show for it (boardLoad sends the one it
  // shows the same way). The database only keeps it if it beats that name's row.
  function boardSend(key, name, score) {
    if (!name || !(score > 0) || !BOARD_URL || !BOARD_POSTS || boardDemo) return Promise.resolve();
    return boardFetch(key + '/' + boardKey(name) + '.json', { method: 'PUT', body: JSON.stringify({ name, score: BOARDS[key].low ? -score : score, t: { '.sv': 'timestamp' } }) })
      .catch(() => {});
  }
  // The top ten at one game, with your own row picked out (and added underneath if you didn't make the list).
  function Leaderboard(p) {
    const b = BOARDS[p.key], name = playerName || store.get('name') || '', id = boardKey(name);
    // a net board has columns for what's been won and lost, then the difference
    const fmt = (v) => (b.net ? signed(v) : boardFmt(p.key, v));
    const y0 = b.net ? 50 : 42, gap = b.net ? 15 : 16;
    let rows = null, mine = null, failed = false, t = 0;
    boardLoad(p.key, name, p.score).then((r) => {
      rows = r.rows; mine = r.mine;
      awayBoard(p.key, name, rows); // (you've seen where you are on it now)
      // (a quest's board has just been sent to, so this says if that's put you on top)
      if (b.quest && rows.length && name && name !== 'New Hire') setQuestTop(p.key, rows[0].id === id);
      // (and if a game's has just gone up with you in its top ten, it might have made you number 1)
      const improved = b.net || (p.score > 0 && !!mine && mine.score === (b.low ? -p.score : p.score));
      if (improved && rows.some((r) => r.id === id)) champWatch(name);
    }, () => { failed = true; });
    const right = (str, x, y, c) => text(str, x - str.length * 6, y, 1, c);
    const row = (rank, who, r, y, me) => {
      if (me) pickBar(16, y - 4, SW - 32, 15, col.dark);
      const c = me ? col.light : col.dark;
      text(rank, 24, y, 1, c);
      text(who, 50, y, 1, c);
      if (b.net) { right(String(r.won), 188, y, c); right(String(r.lost), 242, y, c); }
      right(fmt(r.score), SW - 24, y, c);
    };
    const self = {
      point: anyClick,
      update() {
        t++;
        if (t > 20 && (pressed.has('a') || pressed.has('b'))) { sfx('menu'); remove(self); }
      },
      draw() {
        box(0, 0, SW, SH);
        ctext('LEADERBOARD', 10);
        ctext(b.title, 23);
        if (failed) ctext('Leaderboard unavailable', 110);
        else if (!rows) ctext('Loading...', 110);
        else if (!rows.length) ctext('No scores yet', 110);
        else {
          if (b.net) [['WON', 188], ['LOST', 242], ['NET', SW - 24]].forEach(([h, x]) => right(h, x, 37, '#686878'));
          rows.forEach((r, i) => row((i + 1) + '.', r.name, r, y0 + i * gap, name && r.id === id));
          if (mine && !rows.some((r) => r.id === id)) row('-', name, mine, 204, true);
          else if (name && rows[0].id === id) { drawCrown(97, 205); text('You hold the crown!', 109, 204, 1, GOLD); }
        }
        if (t > 20 && (tick >> 4) & 1) ctext('Press Space', SH - 16);
      },
    };
    return self;
  }

  // ---------- play time ----------
  // How long each name has spent playing, kept in the database for you to look at (see "Play time"
  // in the README) as playtime/<world>/<name> = { name, s: the seconds all told, t: when it was last
  // added to }. Only you get PLAY TIME in the start menu, but the rules let anybody read it straight
  // from the database, since that menu has to.
  //
  // Only time with the game in front of somebody counts. The tab has to be showing and its window
  // the one in use (on a phone, just showing), and somebody has to be there: the time since your
  // last press (a key, a button, a controller, a tap, the mouse moving) counts when you next press
  // something, as long as that's under PLAY_IDLE. Any longer and it's dropped, so a game left open
  // while you go for lunch adds nothing. What's counted waits in this browser until it's sent, every
  // minute and as the page is put away, so time played offline goes when it's back. The database adds
  // it to what's there (the increment), so a phone and a computer add up.
  const PLAY_IDLE = 5 * 60 * 1000, PLAY_EVERY = 60 * 1000;
  // the most one send can add (the database's rules refuse more); a bigger backlog goes in pieces
  const PLAY_MOST = 600;
  const PLAY_KEY = (BOARD_POSTS ? '' : 'test.') + 'playtime';
  const PLAY_URL = BOARD_URL && !boardDemo ? BOARD_URL.replace(/\/+$/, '') + '/playtime/' + (BOARD_POSTS ? 'live' : 'test') + '/' : '';
  // ms in front of somebody since their last press, ms counted but not yet a whole second, and the clock
  let playSince = 0, playPart = 0, playAt = performance.now(), playWas = false, playSending = false, playLast = playAt;
  const playInFront = () => document.visibilityState === 'visible' && (isTouch || document.hasFocus());
  const playUnsent = () => Math.max(0, Math.floor(+store.get(PLAY_KEY) || 0));
  // Somebody pressed something: the time since the last press was them playing, unless it was too long.
  function playStir() {
    if (playSince <= PLAY_IDLE) playPart += playSince;
    playSince = 0;
    const s = Math.floor(playPart / 1000);
    if (s > 0) { playPart -= s * 1000; store.set(PLAY_KEY, String(playUnsent() + s)); }
  }
  // Every second: the clock runs while the game's in front (from the second second, so time spent
  // away doesn't count), and every so often what's been counted goes to the database.
  function playTick() {
    const now = performance.now(), on = playInFront();
    if (on && playWas) playSince = Math.min(playSince + Math.min(now - playAt, 5000), PLAY_IDLE + 1);
    playAt = now; playWas = on;
    // (more than one send's worth waiting: the rest goes soon after, not in another minute)
    if (now - playLast >= (playUnsent() > PLAY_MOST ? 5000 : PLAY_EVERY)) playSend(false);
  }
  // Send what's waiting under the name you're playing as. With leaving, it's sent even if the page
  // closes (keepalive). It only comes off what's waiting once the database has it.
  function playSend(leaving) {
    if (!PLAY_URL || playSending || mode === 'name') return; // (not while the name is being typed)
    playLast = performance.now();
    const name = playerName || store.get('name') || '', s = Math.min(playUnsent(), PLAY_MOST);
    if (!s || !name || name === 'New Hire') return;
    playSending = true;
    const ac = new AbortController(), timer = setTimeout(() => ac.abort(), 10000);
    fetch(PLAY_URL + boardKey(name) + '.json', {
      method: 'PATCH', keepalive: leaving, signal: ac.signal,
      body: JSON.stringify({ name, s: { '.sv': { increment: s } }, t: { '.sv': 'timestamp' } }),
    }).then((r) => { if (r.ok) store.set(PLAY_KEY, String(Math.max(0, playUnsent() - s))); })
      .catch(() => {}) // (it waits for next time)
      .finally(() => { clearTimeout(timer); playSending = false; });
  }
  // The names that get PLAY TIME in the start menu (only with their password: see LOCKED)
  const PLAY_TIME_FOR = ['warren'];
  const seesPlayTime = () => PLAY_TIME_FOR.includes(lockName(playerName)) && unlocked(playerName);
  // 3h 05m, 12m, 40s
  const playFmt = (s) => (s < 60 ? s + 's' : s < 3600 ? Math.floor(s / 60) + 'm'
    : Math.floor(s / 3600) + 'h ' + String(Math.floor((s % 3600) / 60)).padStart(2, '0') + 'm');
  // Everybody's play time, A to Z, with when they last played. (The test page makes some up.)
  function PlayTimeList() {
    let rows = null, failed = false, scroll = 0, t = 0;
    const SHOWN = 11, rep = heldRepeat();
    const got = boardDemo ? Promise.resolve(Object.fromEntries(DEMO_NAMES.map((n, i) => [boardKey(n), { name: n, s: 400 + ((i * 7919) % 23) * 1777, t: Date.now() - i * 5400000 }])))
      : PLAY_URL ? fetch(PLAY_URL.replace(/\/$/, '') + '.json').then((r) => (r.ok ? r.json() : Promise.reject(new Error('play time ' + r.status))))
      : Promise.reject(new Error('no database'));
    got.then((all) => {
      rows = Object.entries(all || {}).filter(([, r]) => r && typeof r.s === 'number' && r.s > 0)
        .map(([id, r]) => ({ name: String(typeof r.name === 'string' ? r.name : id).slice(0, NAME_MAX), s: Math.floor(r.s), t: +r.t || 0 }))
        .sort((a, b) => a.name.toLowerCase().localeCompare(b.name.toLowerCase()));
    }, () => { failed = true; });
    const room = () => (rows ? Math.max(0, rows.length - SHOWN) : 0);
    const right = (str, x, y, c) => text(str, x - str.length * 6, y, 1, c);
    const self = {
      update() {
        t++;
        if (pressed.has('b') || (pressed.has('a') && t > 10)) { sfx('menu'); remove(self); return; }
        const d = rep();
        if (d === 'up' || d === 'down') {
          const s = Math.max(0, Math.min(room(), scroll + (d === 'up' ? -1 : 1)));
          if (s !== scroll) { scroll = s; sfx('select'); }
        }
      },
      // (a click closes it, as A does, and the wheel scrolls)
      point: anyClick,
      wheel(d) { pressed.add(d > 0 ? 'down' : 'up'); },
      draw() {
        box(0, 0, SW, SH);
        text('PLAY TIME', (SW - 9 * 12) >> 1, 8, 2, col.dark);
        ctext('Everyone, A to Z', 28, '#686878');
        ctx.fillStyle = col.dark; ctx.fillRect(14, 39, SW - 28, 1);
        if (failed) { ctext('Couldn\'t read play time.', 100); ctext('Check the database\'s playtime rules', 116, '#686878'); ctext('(see "Play time" in the README).', 128, '#686878'); }
        else if (!rows) ctext('Loading...', 110);
        else if (!rows.length) ctext('Nobody has any play time yet.', 110);
        else {
          right('PLAYED', 216, 44, '#686878'); right('LAST', SW - 18, 44, '#686878');
          rows.slice(scroll, scroll + SHOWN).forEach((r, i) => {
            const y = 56 + i * 12;
            text(r.name, 20, y);
            right(playFmt(r.s), 216, y);
            right(r.t ? ago(r.t) : '', SW - 18, y, '#686878');
          });
          scrollBar(SW - 10, 54, 56 + SHOWN * 12 - 2, scroll, SHOWN, rows.length);
          ctx.fillStyle = col.mid; ctx.fillRect(14, 190, SW - 28, 1);
          ctext(rows.length + (rows.length === 1 ? ' name, ' : ' names, ') + playFmt(rows.reduce((n, r) => n + r.s, 0)) + ' in all', 196);
        }
        ctext(room() ? 'Up/down: scroll   Esc: close' : 'Esc: close', SH - 16, '#686878');
      },
    };
    return self;
  }
  // (press() stirs it too, for the on-screen buttons and a controller)
  for (const ev of ['keydown', 'pointerdown', 'pointermove', 'wheel']) addEventListener(ev, playStir, { capture: true, passive: true });
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden') playSend(true); });
  addEventListener('pagehide', () => playSend(true));
  setInterval(() => { try { playTick(); } catch (e) { console.error(e); } }, 1000);

  // ---------- the Hall of Fame: every board at once, on the wall in reception ----------
  // Each board's top ten earn points towards Office Champion (10 for 1st down to 1 for
  // 10th), and holding 1st is a crown. The games are grouped by where you find them;
  // a board left out of FAME_GROUPS still turns up, under OTHER. The quests (Linda and
  // Employee of the Month) earn points and crowns the same way, on a QUESTS page of their own
  // listing everyone who has done them.
  const FAME_GROUPS = [
    ['OFFICE', ['coffee', 'toss', 'lunch', 'candy', 'stack', 'simon', 'desk', 'jam', 'filter']],
    ['FITNESS ROOM', ['punch5', 'squat', 'run', 'pullreps', 'ball', 'laundry']],
    ['SCREENS AND CODY\'S CASINO', ['pong', 'snake', 'galaxy', 'poker', 'pokerlive', 'blackjack', 'slots']],
    ['BOARDROOM AND 2ND FLOOR', ['fan', 'coil', 'damper', 'parts', 'cable', 'cprpts', 'engrave', 'golf9', 'legosolo']],
    ['COWORKERS AND DOGS', ['dark', 'dancepts', 'trophy', 'forms', 'wokpieces', 'carrotpts', 'legolines', 'catchrun']],
    ['BOARD AND CARD GAMES', ['chess', 'checkers', 'cards', 'cardwins']],
    ['HAAKON GRAND PRIX', ['racelake', 'racemaple', 'racesnow', 'raceprairie', 'raceplant']],
    ['KINGSTON PLANT', ['forklift', 'paint']],
    ['HALLOWEEN', ['bob', 'mummy', 'carve', 'treat', 'ghosts', 'costumepts']],
    ['CHRISTMAS', ['chop', 'mallow', 'spruce', 'snowman', 'cocoa', 'snowball', 'hockey', 'humbug']],
  ];
  // The holidays' games stay out of the Hall of Fame altogether (their page, the champions'
  // points and the latest scores) until the day that holiday first came round, so scores
  // put in early while trying them out don't show; from then on they're there for good.
  // Forcing the holiday on (&christmas=1) shows them early, on that screen only.
  const SEASON_FROM = { HALLOWEEN: new Date(2026, 9, 1), CHRISTMAS: new Date(2026, 10, 27) };
  const GOLD = '#c08818', MEDALS = [GOLD, '#8890a0', '#b06830'];
  const pts = (n) => n + (n === 1 ? ' pt' : ' pts');
  const nth = (n) => n + ((n % 100 >= 11 && n % 100 <= 13) ? 'th' : ['th', 'st', 'nd', 'rd'][n % 10] || 'th');
  // the end of a sentence, for one that ends on someone's name: it may have a period already ("Maya J.")
  const sentence = (str) => (str.endsWith('.') ? str : str + '.');
  function ago(t) {
    const m = Math.max(0, Date.now() - t) / 60000;
    return m < 1 ? 'just now' : m < 60 ? Math.floor(m) + 'm ago' : m < 1440 ? Math.floor(m / 60) + 'h ago' : Math.floor(m / 1440) + 'd ago';
  }
  function drawCrown(x, y) {
    // three points with a ball on each, a band across the bottom and a shine along it
    fine(x, y + 0.5, 1, 2, '#f0b030'); fine(x + 3, y + 0.5, 1, 2, '#f0b030'); fine(x + 6, y + 0.5, 1, 2, '#f0b030');
    fine(x + 0.5, y + 1.5, 6, 1, '#f0b030'); fine(x + 1, y + 1, 1, 1, '#f0b030'); fine(x + 2, y + 1.5, 1, 0.5, '#f0b030'); fine(x + 4, y + 1.5, 1, 0.5, '#f0b030'); fine(x + 5, y + 1, 1, 1, '#f0b030');
    fine(x, y + 2, 7, 3, '#f0b030'); fine(x, y + 4.5, 7, 0.5, '#b87810');
    fine(x, y + 0.5, 0.5, 2, '#f8d868'); fine(x + 3, y + 0.5, 0.5, 2, '#f8d868'); fine(x + 6, y + 0.5, 0.5, 2, '#f8d868'); fine(x, y + 2.5, 7, 0.5, '#f8d868');
    for (const b of [0, 3, 6]) fine(x + b + 0.25, y, 0.5, 0.5, '#fff0b0');
    fine(x + 3, y + 3, 1, 1, '#b83028'); fine(x + 3, y + 3, 0.5, 0.5, '#f06858');
    fine(x + 1, y + 3.5, 0.5, 0.5, '#2858a8'); fine(x + 5.5, y + 3.5, 0.5, 0.5, '#2858a8');
  }
  // Every row of one board, best first. A net board's rows also have won and lost, its two
  // halves (see netNote), and its score is the difference.
  function boardAll(key, name) {
    const b = BOARDS[key] || {};
    if (b.net) {
      // (made up: won and lost picked separately for each name, and never a blank board)
      const half = (k) => (!boardDemo ? boardAll(key + k, name) : Promise.resolve(DEMO_NAMES.concat(name ? [name] : [])
        .filter((n) => hash(key + n) % 3).map((n) => ({ id: boardKey(n), name: n, score: hash(n + key + k) % 400 + 1, t: Date.now() - hash(key + n) % 6e8 }))));
      return Promise.all([half('won'), half('lost')]).then(([won, lost]) => {
        const rows = {};
        for (const [half, k] of [[won, 'won'], [lost, 'lost']]) for (const r of half) {
          const row = rows[r.id] || (rows[r.id] = { id: r.id, name: r.name, won: 0, lost: 0, t: 0 });
          row[k] = r.score; row.t = Math.max(row.t, r.t);
        }
        return Object.values(rows).map((r) => Object.assign(r, { score: r.won - r.lost })).sort(byScore);
      });
    }
    if (boardDemo) {
      // a different made-up crowd at each game (you among them now and then), and a few boards nobody has played
      if (hash(key) % 6 === 0) return Promise.resolve([]);
      const crowd = DEMO_NAMES.concat(name ? [name] : []).filter((n) => hash(key + n) % 3);
      return Promise.resolve(crowd.map((n) => {
        const v = b.count ? hash(n + key) % 4 + 1 : hash(n + key) % 400 + 1;
        return { id: boardKey(n), name: n, score: b.low ? -v : v, t: Date.now() - hash(key + n) % 6e8 };
      }).sort(byScore));
    }
    return boardFetch(key + '.json').then((r) => {
      if (!r.ok) throw new Error('board ' + r.status);
      return r.json();
    }).then(boardRows);
  }
  // The boards in the Hall of Fame, leaving out any holiday that hasn't come round yet (see
  // SEASON_FROM): `keys` is all of them, each earning points, and `groups` the games' pages.
  function fameBoards() {
    const SEASON = { HALLOWEEN, CHRISTMAS }, early = (g) => g in SEASON_FROM && !SEASON[g] && Date.now() < SEASON_FROM[g];
    const shown = FAME_GROUPS.filter(([g]) => !early(g)), hidden = new Set(FAME_GROUPS.filter(([g]) => early(g)).flatMap(([, k]) => k));
    const keys = Object.keys(BOARDS).filter((k) => !hidden.has(k) && !BOARDS[k].unlisted), games = keys.filter((k) => !BOARDS[k].quest), grouped = new Set(FAME_GROUPS.flatMap(([, k]) => k));
    return { keys, groups: shown.concat([['OTHER', games.filter((k) => !grouped.has(k))]]) };
  }
  // Everyone in the running for Office Champion, best first, from every board in keys
  // (boards[key], best first): points for each top ten, then crowns to break a tie.
  function fameStandings(boards, keys) {
    const pts = {};
    for (const k of keys) (boards[k] || []).slice(0, 10).forEach((r, i) => {
      const s = pts[r.id] || (pts[r.id] = { id: r.id, name: r.name, points: 0, crowns: 0 });
      s.points += 10 - i;
      if (!i) s.crowns++;
    });
    return Object.values(pts).sort((a, b) => b.points - a.points || b.crowns - a.crowns || a.name.localeCompare(b.name));
  }
  // Every board in the Hall of Fame (see fameBoards), each best first, as { key: rows }, with
  // null for one that couldn't be had; or null if none of them could.
  function fameAll(name) {
    const { keys } = fameBoards();
    return Promise.all(keys.map((k) => boardAll(k, name).catch(() => null))).then((all) => {
      if (all.every((r) => r === null)) return null;
      const boards = {};
      keys.forEach((k, i) => { boards[k] = all[i]; });
      return boards;
    });
  }
  // Whether a name is the Office Champion right now, from every board as the Hall of
  // Fame has them: null if none of the boards can be had. A New Hire never is. seen, if
  // it's there, gets the boards as well (see awaySeen).
  function crownCheck(name, seen) {
    if (!name || name === 'New Hire' || !(BOARD_URL || boardDemo)) return Promise.resolve(false);
    return fameAll(name).then((boards) => {
      if (!boards) return null;
      if (seen) seen(boards);
      const top = fameStandings(boards, Object.keys(boards))[0];
      return !!top && top.id === boardKey(name);
    }, () => null);
  }
  // What the boards say about a name and the title (true, false, or null if they can't say,
  // which only counts as you come in). You get the title or lose it there and then, and you're
  // told about getting it, once each time you get there (kept in this browser).
  function champHeard(name, on, comingIn) {
    if (on === null && !comingIn) return;
    // (the title's changing hands while you play, so what you chose last time doesn't count;
    // as you come in, editStart sees to that, with the look saved under your name)
    if (!comingIn && !!on !== crowned && myLook.champOff) { myLook = Object.assign({}, myLook, { champOff: 0 }); lookKeep(); }
    setCrowned(!!on);
    const told = 'champ.told.' + boardKey(name);
    if (on === false) store.set(told, '');
    if (!on || store.get(told)) return;
    store.set(told, '1');
    questEarned.unshift({ what: 'You\'re number 1! Crown (HEAD), Star trail (FLAIR)', champ: true, told: champSay });
    if (mode === 'play') questTell();
  }
  function champSay() {
    sfx('cup');
    ui.push(Dialog('You\'re number 1! You\'ve taken the top spot in the Hall of Fame, and that makes you the Office Champion. The crown and the star trail are yours for as long as you stay on top. If you don\'t want to wear them, change them under Edit character in the Start menu.', { above: itemPanel(['crown', 'startrail']) }));
  }
  // A score of yours has just gone up: has that done it?
  let champWatching = false;
