    f(3, 6, 10, 0.5, lit); f(3, 6.5, 0.5, 5, lit); f(12.5, 7, 0.5, 4.5, dim); f(3, 11.5, 10, 0.5, dim);
    f(5.5, 8, 5, 0.5, '#888898'); f(5, 8.5, 0.5, 1, '#888898'); f(5.5, 9.5, 5, 0.5, '#383848'); f(10.5, 8.5, 0.5, 1, '#383848');
