      ctx.save(); ctx.translate(f.x, f.y); ctx.rotate(tilt());
      ctx.drawImage(sprites.up[!moving ? 0 : h < 1 ? 1 + ((t >> 3) & 1) : 1 + (step & 1)], -16, -31, 32, 32);
      ctx.restore();
