    const ground = ([u, , f]) => [S * f + C * u * hand, C * f - S * u * hand];
    const [hx, hy] = ground(heel), [tx, ty] = ground(top);
    const x0 = fx + hx * 16, y0 = fy + hy * 16 - heel[1] * 9, x1 = fx + tx * 16, y1 = fy + ty * 16 - top[1] * 9;
