    pixLine(x0, y0, x1, y1, 1, '#d8b07a'); pixLine(x1 + (x0 - x1) * 0.1, y1 + (y0 - y1) * 0.1, x1, y1, 1, '#22222a');
    pixLine(x0, y0, bx, by, 1.5, '#303038'); pixLine(bx + (x0 - bx) * 0.5, by + (y0 - by) * 0.5, bx, by, 1, '#f4f6fa');
