      const fx = realPx(p.x * 16 + 7 - cx), fy = realPx(p.y * 16 + 10 - cy);
      if (p.mark === 'hoof') { fine(fx, fy, 1, 1, '#8a9cc0'); fine(fx + 1.5, fy, 1, 1, '#8a9cc0'); } // (a hoof's in two halves)
