        const a = f.seed + j * Math.PI * 2 / 7, sp = 0.2 + 0.1 * (j % 3);
        fine(realPx(f.x * 16 + 8 - cx + Math.cos(a) * sp * age), realPx(f.y * 16 + 10 - cy + Math.sin(a) * sp * age * 0.5 - Math.max(0, f.z * UP + (0.4 - 0.018 * age) * age)), 1.5, 1.5, '#f6f8fc');
